import React, { useState, useEffect, createContext, useContext, useRef } from 'react';
import { storageService } from './services/storageService';
import { lotteryService } from './services/lotteryService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import { User, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase, Hospital as HospitalIcon, ArrowRight, Zap } from 'lucide-react';
import { UserRole, AuthUser, SessionType } from './types';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  const autoRunLogs = useRef<Set<string>>(new Set());

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { 
      setUser(session); 
      setView('DASHBOARD'); 
    }

    const automationInterval = setInterval(() => {
      const now = new Date();
      const today = now.toISOString().split('T')[0];
      const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      const hospitals = storageService.getHospitals();
      hospitals.forEach(hosp => {
        if (!hosp.isActive || !hosp.autoLotteryEnabled) return;

        (['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).forEach(sess => {
          const isEnabled = hosp.autoLotteryEnabled?.[sess];
          const triggerTime = hosp.autoLotteryTimes?.[sess];

          if (isEnabled && triggerTime && currentTimeStr >= triggerTime) {
            const logKey = `${hosp.id}-${today}-${sess}`;
            if (!autoRunLogs.current.has(logKey)) {
              const result = lotteryService.runLottery(hosp.id, sess);
              if (result.success) {
                console.log(`[AUTOMATION] Triggered lottery for ${hosp.name} (${sess})`);
                autoRunLogs.current.add(logKey);
                const currentUser = storageService.getCurrentUser();
                if (currentUser?.hospitalId === hosp.id && currentUser.role === 'ADMIN') {
                  showFeedback(`Scheduled lottery for ${sess} executed automatically!`, 'success');
                }
              } else {
                if (result.message === "No applications found.") {
                   autoRunLogs.current.add(logKey);
                }
              }
            }
          }
        });
      });
    }, 15000);

    return () => clearInterval(automationInterval);
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();

    if (role === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.loginId === mobile);
      if (existing) {
        if (existing.status === 'suspended') {
          showFeedback("Your account has been suspended by your company.", 'error');
          return;
        }
        if (existing.password && existing.password !== password) {
          showFeedback("Invalid credentials.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: existing.id, 
          fullName: existing.fullName, 
          role: 'MR', 
          companyName: existing.companyName, 
          loginId: existing.loginId,
          mobileNumber: existing.mobileNumber 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Welcome back, ${u.fullName}!`);
      } else {
        showFeedback("Medical Representative not found.", 'error');
      }
    } else if (role === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === mobile);
      if (found && found.adminPassword === password) {
        if (!found.isActive) {
          showFeedback("Company access is deactivated.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: found.id, 
          role: 'COMPANY_ADMIN', 
          fullName: `${found.name} Admin`,
          companyId: found.id 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Pharma Admin session: ${found.name}`);
      } else {
        showFeedback("Invalid Company Admin credentials.", 'error');
      }
    } else if (role === 'ADMIN' || role === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === mobile && u.role === role);

      if (found) {
        if (found.password === password) {
          const u: AuthUser = { 
            id: found.id,
            role: found.role, 
            fullName: found.fullName, 
            hospitalId: found.hospitalId,
            mobileNumber: found.mobileNumber
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Logged in as ${found.fullName}`);
        } else {
          showFeedback("Invalid password for this account.", 'error');
        }
      } else {
        showFeedback(`${role} credentials not found. Check with Super Admin.`, 'error');
      }
    } else if (role === 'SUPER_ADMIN') {
      if (mobile === 'root' && password === 'root') {
        const u: AuthUser = { id: 'sa-1', role: 'SUPER_ADMIN', fullName: 'MedPass Authority' };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback("Super Admin session started.");
      } else {
        showFeedback("Invalid Super Admin Credentials", 'error');
      }
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); 
    setMobile(phone);
    setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex flex-col items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden mb-12">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">System Demo Credentials</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => quickLogin('MR', 'john_mr', 'pass')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                    <User className="h-3 w-3 mb-1" /> MR John
                  </button>
                  <button onClick={() => quickLogin('COMPANY_ADMIN', '0779', 'pfiz')} className="p-2 bg-indigo-50 border border-indigo-100 rounded text-[10px] font-bold text-indigo-700 flex flex-col items-center">
                     <Briefcase className="h-3 w-3 mb-1" /> Pharma Admin
                  </button>
                  <button onClick={() => quickLogin('ADMIN', '0771', 'admin')} className="p-2 bg-slate-50 border border-slate-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                     <ShieldCheck className="h-3 w-3 mb-1" /> Hospital Admin
                  </button>
                  <button onClick={() => quickLogin('SUPER_ADMIN', 'root', 'root')} className="p-2 bg-slate-800 border border-slate-700 rounded text-[10px] font-bold text-white flex flex-col items-center">
                     <Crown className="h-3 w-3 mb-1" /> Super Admin
                  </button>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto scrollbar-hide">
                {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">{role === 'MR' ? 'Login User ID' : 'Login ID / Mobile'}</label>
                  <input 
                    type="text" 
                    value={mobile} 
                    onChange={e => setMobile(e.target.value)} 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                    placeholder={role === 'MR' ? "e.g. john_mr" : role === 'SUPER_ADMIN' ? "root" : "Admin ID"}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                  <div className="relative">
                    <input 
                      type="password" 
                      value={password} 
                      onChange={e => setPassword(e.target.value)} 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                      placeholder="••••••••"
                    />
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  </div>
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                  Enter System <ArrowRight className="h-5 w-5" />
                </button>
              </form>
            </div>
          </div>

          <div className="flex flex-col items-center grayscale opacity-30 hover:grayscale-0 hover:opacity-100 transition-all cursor-default group">
            <div className="flex items-center gap-3 mb-2">
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-100">Powered by</span>
              <div className="flex items-center gap-1.5 bg-slate-900 backdrop-blur-md px-4 py-2 rounded-2xl border border-white/20 shadow-xl group-hover:border-indigo-400 transition-all">
                <Zap className="h-4 w-4 text-indigo-400" />
                <span className="text-sm font-black text-white tracking-tighter lowercase">dren</span>
              </div>
            </div>
            <p className="text-[9px] font-bold text-indigo-200 uppercase tracking-widest opacity-60">Personal Field Intelligence</p>
          </div>

          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user!} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); showFeedback("Logged out successfully"); }} 
        title={user?.role === 'SUPER_ADMIN' ? 'Root Authority' : user?.role === 'MR' ? 'MR Dashboard' : `${user?.fullName} Panel`}
      >
        {user?.role === 'MR' && <MRDashboard user={user as any} />}
        {user?.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user?.role === 'ADMIN' && <AdminDashboard user={user as any} />}
        {user?.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user?.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext, useMemo } from 'react';
import { ShieldCheck, QrCode, User, CheckCircle, Smartphone, Clock, Users, MapPin, Zap } from 'lucide-react';
import { storageService } from '../services/storageService';
import { EntryLog, MedicalRep, Hospital } from '../types';
import { FeedbackContext } from '../App';

const SecurityView: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospital, setHospital] = useState<Hospital | null>(null);

  // The fixed Gate QR data
  const gateQrValue = useMemo(() => {
    const user = storageService.getCurrentUser();
    return user?.hospitalId ? `MEDPASS-GATE-${user.hospitalId}` : 'INVALID-GATE';
  }, []);

  useEffect(() => {
    const refresh = () => {
      const user = storageService.getCurrentUser();
      if (user?.hospitalId) {
        const allHospitals = storageService.getHospitals();
        setHospital(allHospitals.find(h => h.id === user.hospitalId) || null);

        // Filter logs for this hospital's passes
        const allLogs = storageService.getLogs();
        const allPasses = storageService.getPasses();
        const myPassIds = allPasses
          .filter(p => p.hospitalId === user.hospitalId)
          .map(p => p.id);

        const filteredLogs = allLogs
          .filter(l => myPassIds.includes(l.issuedPassId))
          .sort((a, b) => new Date(b.entryTime).getTime() - new Date(a.entryTime).getTime());

        setLogs(filteredLogs);
        setMrs(storageService.getMRs());
      }
    };

    refresh();
    const interval = setInterval(refresh, 5000); // Poll for new entries
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in duration-500">
      {/* Left Column: Fixed Gate QR Display */}
      <section className="bg-white p-10 rounded-[3rem] shadow-2xl border border-indigo-100 flex flex-col items-center text-center relative overflow-hidden h-fit sticky top-24">
        <div className="absolute -top-10 -left-10 w-40 h-40 bg-indigo-50 rounded-full blur-3xl opacity-50"></div>
        <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-indigo-50 rounded-full blur-3xl opacity-50"></div>

        <div className="bg-indigo-600 p-4 rounded-3xl w-fit mb-6 shadow-xl shadow-indigo-100 relative z-10">
          <ShieldCheck className="h-10 w-10 text-white" />
        </div>

        <h3 className="text-3xl font-black text-slate-800 mb-2 tracking-tight relative z-10">Gate Entry Point</h3>
        <p className="text-slate-500 font-bold mb-8 uppercase tracking-widest text-xs flex items-center justify-center gap-2 relative z-10">
          <MapPin className="h-3.5 w-3.5 text-indigo-500" />
          {hospital?.name || 'Loading Facility...'}
        </p>

        <div className="relative group p-4">
          <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-indigo-700 rounded-[2.5rem] blur opacity-25 group-hover:opacity-40 transition duration-1000 group-hover:duration-200 animate-pulse"></div>
          <div className="relative bg-white p-8 rounded-[2rem] border-2 border-indigo-50 shadow-inner">
             {/* In a real app, this would use a QR generator library. For now, we use a placeholder icon representing the scan target. */}
             <div className="relative flex items-center justify-center">
                <QrCode className="h-64 w-64 text-indigo-900" />
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-10">
                   <Zap className="h-20 w-20 text-indigo-600 animate-bounce" />
                </div>
             </div>
          </div>
        </div>

        <div className="mt-10 space-y-4 w-full">
           <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-100">
              <p className="text-xs font-black text-indigo-800 uppercase tracking-widest mb-1">Gate Identifier</p>
              <p className="font-mono text-lg font-black text-indigo-600">{gateQrValue}</p>
           </div>
           <div className="flex items-center justify-center gap-3 py-4 text-slate-400">
              <Smartphone className="h-5 w-5 animate-bounce" />
              <p className="text-sm font-bold italic">MRs: Please scan this code with your MedPass App</p>
           </div>
        </div>
      </section>

      {/* Right Column: Live Entry Log */}
      <section className="bg-white rounded-[3rem] shadow-xl border border-slate-100 overflow-hidden flex flex-col min-h-[600px]">
        <div className="p-8 border-b border-slate-50 bg-slate-50/50 flex justify-between items-center">
           <div>
              <h3 className="text-xl font-black text-slate-800">Live Access Logs</h3>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Real-time gate traffic</p>
           </div>
           <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-xl border border-slate-200 shadow-sm">
              <div className="w-2 h-2 bg-green-500 rounded-full animate-ping"></div>
              <span className="text-[10px] font-black text-slate-600 uppercase">Live Feed</span>
           </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
           {logs.map((log, index) => {
             const passes = storageService.getPasses();
             const pass = passes.find(p => p.id === log.issuedPassId);
             const mr = mrs.find(m => m.id === pass?.mrId);

             return (
               <div key={log.id} className={`flex items-center justify-between p-5 rounded-[2rem] border transition-all animate-in slide-in-from-right-4 duration-300 ${index === 0 ? 'bg-indigo-50/50 border-indigo-100 shadow-md ring-2 ring-indigo-500/10' : 'bg-white border-slate-100'}`}>
                  <div className="flex items-center gap-4">
                     <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 shadow-sm ${index === 0 ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-400'}`}>
                        {index === 0 ? <CheckCircle className="h-6 w-6" /> : <User className="h-6 w-6" />}
                     </div>
                     <div>
                        <p className="font-black text-slate-800 leading-tight">{mr?.fullName || 'Unknown MR'}</p>
                        <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-tight">{mr?.companyName || 'Visitor'}</p>
                     </div>
                  </div>
                  <div className="text-right">
                     <div className="flex items-center justify-end gap-1.5 text-slate-800 font-black text-sm">
                        <Clock className="h-3 w-3 text-slate-300" />
                        {new Date(log.entryTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                     </div>
                     <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Pass: {log.issuedPassId}</p>
                  </div>
               </div>
             );
           })}

           {logs.length === 0 && (
             <div className="h-full flex flex-col items-center justify-center py-20 text-slate-300">
                <Users className="h-16 w-16 mb-4 opacity-10" />
                <p className="text-sm font-bold uppercase tracking-widest">Waiting for entries...</p>
                <p className="text-[10px] mt-1 italic">Entries will appear here as soon as MRs scan the gate QR.</p>
             </div>
           )}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 text-center">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Validated Today: {logs.length}</p>
        </div>
      </section>
    </div>
  );
};

export default SecurityView;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, ChevronRight, MapPin, XCircle, Camera, X, Smartphone
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');

  // Scanner States
  const [isScanning, setIsScanning] = useState(false);
  const [stream, setStream] = useState<MediaStream | null>(null);

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);

    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const startScanner = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
      setIsScanning(true);
    } catch (err) {
      console.error("Scanner access error:", err);
      showFeedback("Could not access camera. Check permissions.", "error");
    }
  };

  const stopScanner = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
    setIsScanning(false);
  };

  const simulateScan = (simulatedValue?: string) => {
    // In a real app, a QR library would decode the value from the video frame.
    // For this prototype, we'll prompt the user or allow clicking a button to "simulate" a scan detection.
    const qrValue = simulatedValue || prompt("Simulate Scan: Please enter the Gate QR Identifier (e.g. MEDPASS-GATE-h1)");
    if (!qrValue) return;

    if (!qrValue.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid Gate QR Code detected.", "error");
      return;
    }

    const hospitalId = qrValue.replace('MEDPASS-GATE-', '');
    const today = new Date().toISOString().split('T')[0];

    // Find valid active pass for this hospital today
    const activePass = passes.find(p => 
      p.hospitalId === hospitalId && 
      p.passDate === today && 
      p.entryStatus === 'not_entered'
    );

    if (!activePass) {
      showFeedback("No active pass found for this hospital today.", "error");
      return;
    }

    // Process entry
    const allPasses = storageService.getPasses();
    const updatedPasses = allPasses.map(p => 
      p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p
    );

    const log = {
      id: Math.random().toString(36).substr(2, 9),
      issuedPassId: activePass.id,
      entryTime: new Date().toISOString(),
      verifiedBy: 'Self-Gate-Scan'
    };

    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...storageService.getLogs(), log]);

    stopScanner();
    refreshData();
    showFeedback("Entry Validated! You may proceed to the gate.", 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;

    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');

    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { showFeedback(reason || "Ineligible", 'error'); return; }

    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Application already submitted for this session today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      showFeedback("Pass application submitted successfully!");
    }, 600);
  };

  const requestApproval = (hospitalId: string) => {
    const existing = approvals.find(a => a.mrId === user.id && a.hospitalId === hospitalId);
    if (existing && existing.status !== 'rejected') return;

    const newApproval: MRHospitalApproval = {
      id: 'apprv-' + Math.random().toString(36).substr(2, 9),
      mrId: user.id,
      hospitalId,
      status: 'pending',
      updatedAt: new Date().toISOString()
    };

    const updated = existing 
      ? approvals.map(a => a.id === existing.id ? newApproval : a)
      : [...approvals, newApproval];

    storageService.saveApprovals(updated);
    refreshData();
    showFeedback("Access request sent to hospital admin.");
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  const availableHospitals: Hospital[] = hospitals.filter(h => h.isActive && 
    !approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  ).filter(h => h.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const activePassesToday = passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]);

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> My Profile</button>
      </div>

      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Analyzing your profile and calculating your ranking factors..."}</p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <Building2 className="h-5 w-5 text-indigo-500" /> Authorized Hospitals
            </h3>
            <div className="grid gap-6 sm:grid-cols-2">
              {approvedHospitals.map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-shadow group">
                  <div className="mb-4">
                    <p className="font-bold text-slate-800 text-lg group-hover:text-indigo-600 transition-colors">{h.name}</p>
                  </div>
                  <div className="space-y-3">
                    {h.supportedSessions.map(sess => {
                      const open = isSessionWindowOpen(h, sess);
                      const window = h.sessionWindows?.[sess];
                      return (
                        <div key={sess} className="space-y-1">
                          <button
                            disabled={!open || loading}
                            onClick={() => handleApply(h.id, sess)}
                            className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all group/btn ${
                              open 
                                ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' 
                                : 'bg-slate-200/50 text-slate-400 cursor-not-allowed grayscale'
                            }`}
                          >
                            <span className="flex items-center gap-2">
                              {sess === 'MORNING' ? <Sun className="h-4 w-4" /> : sess === 'EVENING' ? <Moon className="h-4 w-4" /> : <Maximize className="h-4 w-4" />}
                              {sess}
                            </span>
                            <span className="flex items-center gap-1">
                              {open ? 'APPLY NOW' : 'CLOSED'}
                              {open && <PlusCircle className="h-3 w-3 group-hover/btn:scale-125 transition-transform" />}
                            </span>
                          </button>
                          <div className="flex justify-between px-1 text-[9px] font-bold text-slate-400">
                            <span className="uppercase tracking-tighter">Window: {window?.start} - {window?.end}</span>
                            {open && <span className="text-green-500 animate-pulse">LIVE</span>}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
              {approvedHospitals.length === 0 && (
                <div className="sm:col-span-2 p-12 text-center bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl">
                  <Building2 className="h-8 w-8 text-slate-300 mx-auto mb-4 opacity-30" />
                  <p className="text-sm font-medium text-slate-500">No hospital access yet.</p>
                  <button onClick={() => setActiveTab('directory')} className="text-xs text-indigo-600 font-bold mt-2 hover:underline underline-offset-4 tracking-tight">Browse Hospital Directory →</button>
                </div>
              )}
            </div>
          </section>

          <section className="space-y-6">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <h3 className="text-lg font-bold mb-6 flex items-center justify-between gap-2 text-slate-800">
                <span className="flex items-center gap-2"><QrCode className="h-5 w-5 text-indigo-500" /> My Passes</span>
                {activePassesToday.length > 0 && (
                  <button 
                    onClick={startScanner}
                    className="flex items-center gap-1.5 bg-indigo-600 text-white px-3 py-1.5 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 transition-all shadow-md active:scale-95 animate-bounce"
                  >
                    <Camera className="h-3.5 w-3.5" /> Scan Gate QR
                  </button>
                )}
              </h3>
              <div className="space-y-4">
                {activePassesToday.map(p => (
                  <div key={p.id} className="p-4 bg-indigo-50 border-2 border-indigo-100 rounded-2xl shadow-sm">
                    <div className="flex justify-between items-center mb-3">
                       <div className="flex items-center gap-1.5">
                        {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : p.session === 'EVENING' ? <Moon className="h-3 w-3 text-indigo-400" /> : <Maximize className="h-3 w-3 text-indigo-500" />}
                        <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">{p.session}</span>
                       </div>
                      <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded shadow-xs">{p.passDate}</span>
                    </div>
                    <p className="font-bold text-slate-800 text-sm mb-4 leading-tight">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                    <div className="bg-white p-4 rounded-xl border border-indigo-100 flex items-center justify-between shadow-inner">
                       <div>
                          <p className="text-[9px] font-black text-slate-400 uppercase">Time Slot</p>
                          <p className="text-xs font-black text-slate-700">{p.timeSlot}</p>
                       </div>
                       <div className="flex flex-col items-end">
                          <p className="text-[9px] font-black text-slate-400 uppercase">Pass ID</p>
                          <p className="text-xs font-black text-indigo-600 font-mono">{p.id}</p>
                       </div>
                    </div>
                  </div>
                ))}
                {activePassesToday.length === 0 && (
                  <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-2xl">
                    <p className="text-xs italic">No active passes for today.</p>
                    <p className="text-[10px] mt-1">Select a session on the left to apply.</p>
                  </div>
                )}
              </div>
            </div>

            {activePassesToday.length > 0 && (
              <div className="bg-amber-50 p-6 rounded-3xl border border-amber-100">
                 <div className="flex items-center gap-2 mb-3">
                    <ShieldCheck className="h-5 w-5 text-amber-500" />
                    <h4 className="text-xs font-black text-amber-800 uppercase tracking-widest">Entry Instructions</h4>
                 </div>
                 <ol className="space-y-3">
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">1</span>
                       Arrive at the gate during your slot.
                    </li>
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">2</span>
                       Locate the permanent Gate QR sign.
                    </li>
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">3</span>
                       Click 'Scan Gate QR' above to validate entry.
                    </li>
                 </ol>
              </div>
            )}
          </section>
        </div>
      )}

      {/* Camera Scanner Modal */}
      {isScanning && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="w-full max-w-md relative flex flex-col items-center">
              <button onClick={stopScanner} className="absolute -top-16 right-0 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all">
                <X className="h-6 w-6" />
              </button>

              <div className="w-full aspect-square bg-black rounded-[3rem] border-4 border-white/20 overflow-hidden relative shadow-2xl">
                 <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />

                 {/* Scanner Overlay UI */}
                 <div className="absolute inset-0 flex items-center justify-center">
                    <div className="w-64 h-64 border-2 border-indigo-400 rounded-3xl relative">
                       <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-indigo-500"></div>
                       <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-indigo-500"></div>
                       <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-indigo-500"></div>
                       <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-indigo-500"></div>
                       <div className="w-full h-0.5 bg-indigo-500/50 absolute top-1/2 -translate-y-1/2 animate-pulse shadow-[0_0_15px_rgba(99,102,241,0.5)]"></div>
                    </div>
                 </div>
              </div>

              <div className="mt-8 text-center space-y-4">
                 <div className="flex items-center gap-3 justify-center">
                    <Smartphone className="h-6 w-6 text-indigo-400" />
                    <h3 className="text-xl font-black text-white">Align with Gate QR</h3>
                 </div>
                 <p className="text-indigo-200/60 text-xs font-bold uppercase tracking-widest">Scanning in progress...</p>

                 <div className="pt-8">
                    <button 
                      onClick={() => simulateScan()} 
                      className="px-6 py-3 bg-indigo-600 text-white rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all flex items-center gap-2 mx-auto"
                    >
                       SIMULATE DETECTION <Zap className="h-3.5 w-3.5" />
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'directory' && (
        <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 animate-in fade-in duration-300">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
              <Search className="h-5 w-5 text-indigo-500" /> Hospital Directory
            </h3>
            <div className="relative max-w-md w-full">
              <input 
                type="text" 
                placeholder="Search hospitals..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-medium"
              />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            </div>
          </div>

          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {availableHospitals.map(h => {
              const approval = approvals.find(a => a.mrId === user.id && a.hospitalId === h.id);
              const isPending = approval?.status === 'pending';
              const isRejected = approval?.status === 'rejected';

              return (
                <div key={h.id} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl hover:border-indigo-200 transition-all flex flex-col justify-between">
                  <div>
                    <h4 className="font-bold text-slate-800 mb-1">{h.name}</h4>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight flex items-center gap-1 mb-4"><MapPin className="h-3 w-3" /> {h.address || 'Colombo, Sri Lanka'}</p>
                  </div>

                  {isPending ? (
                    <div className="flex items-center justify-center gap-2 py-3 bg-amber-50 text-amber-600 rounded-xl text-xs font-black uppercase">
                       <Clock className="h-4 w-4" /> Pending Approval
                    </div>
                  ) : isRejected ? (
                    <div className="flex flex-col gap-2">
                       <div className="flex items-center justify-center gap-2 py-3 bg-red-50 text-red-600 rounded-xl text-xs font-black uppercase">
                          <XCircle className="h-4 w-4" /> Request Denied
                       </div>
                       <button onClick={() => requestApproval(h.id)} className="text-[10px] font-bold text-indigo-600 underline">Try Requesting Again</button>
                    </div>
                  ) : (
                    <button 
                      onClick={() => requestApproval(h.id)}
                      className="w-full py-3 bg-white border border-indigo-200 text-indigo-600 font-black rounded-xl text-xs hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                    >
                      REQUEST ACCESS
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </section>
      )}

      {activeTab === 'profile' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm animate-in slide-in-from-bottom-4 duration-500 max-w-2xl mx-auto">
          <div className="flex flex-col items-center mb-8">
            <div className="w-24 h-24 bg-indigo-100 rounded-full flex items-center justify-center mb-4 border-4 border-white shadow-lg">
               <UserCircle className="h-12 w-12 text-indigo-600" />
            </div>
            <h3 className="text-2xl font-black text-slate-800">{user.fullName}</h3>
            <p className="text-indigo-600 font-bold uppercase tracking-widest text-xs mt-1">{user.companyName}</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Login User ID</label>
               <p className="font-bold text-slate-700 font-mono">{user.loginId}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">SLCPI Number</label>
               <p className="font-bold text-slate-700">{user.slcpiId || 'Not registered'}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Mobile Access</label>
               <p className="font-bold text-slate-700">{user.mobileNumber}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">System Join Date</label>
               <p className="font-bold text-slate-700">{new Date(user.createdAt).toLocaleDateString()}</p>
            </div>
          </div>

          <div className="mt-8 pt-8 border-t border-slate-100">
             <div className="flex items-center gap-3 p-4 bg-indigo-50 rounded-2xl border border-indigo-100">
                <ShieldCheck className="h-5 w-5 text-indigo-500" />
                <p className="text-xs font-bold text-indigo-900 leading-tight">Your compliance documents are verified and managed by your company administrator.</p>
             </div>
          </div>
        </section>
      )}
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, ChevronRight, MapPin, XCircle, Camera, X, Smartphone, Zap
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');

  // Scanner States
  const [isScanning, setIsScanning] = useState(false);
  const [stream, setStream] = useState<MediaStream | null>(null);

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);

    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const startScanner = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
      setIsScanning(true);
    } catch (err) {
      console.error("Scanner access error:", err);
      showFeedback("Could not access camera. Check permissions.", "error");
    }
  };

  const stopScanner = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
    setIsScanning(false);
  };

  const simulateScan = (simulatedValue?: string) => {
    // In a real app, a QR library would decode the value from the video frame.
    // For this prototype, we'll prompt the user or allow clicking a button to "simulate" a scan detection.
    const qrValue = simulatedValue || prompt("Simulate Scan: Please enter the Gate QR Identifier (e.g. MEDPASS-GATE-h1)");
    if (!qrValue) return;

    if (!qrValue.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid Gate QR Code detected.", "error");
      return;
    }

    const hospitalId = qrValue.replace('MEDPASS-GATE-', '');
    const today = new Date().toISOString().split('T')[0];

    // Find valid active pass for this hospital today
    const activePass = passes.find(p => 
      p.hospitalId === hospitalId && 
      p.passDate === today && 
      p.entryStatus === 'not_entered'
    );

    if (!activePass) {
      showFeedback("No active pass found for this hospital today.", "error");
      return;
    }

    // Process entry
    const allPasses = storageService.getPasses();
    const updatedPasses = allPasses.map(p => 
      p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p
    );

    const log = {
      id: Math.random().toString(36).substr(2, 9),
      issuedPassId: activePass.id,
      entryTime: new Date().toISOString(),
      verifiedBy: 'Self-Gate-Scan'
    };

    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...storageService.getLogs(), log]);

    stopScanner();
    refreshData();
    showFeedback("Entry Validated! You may proceed to the gate.", 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;

    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');

    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { showFeedback(reason || "Ineligible", 'error'); return; }

    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Application already submitted for this session today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      showFeedback("Pass application submitted successfully!");
    }, 600);
  };

  const requestApproval = (hospitalId: string) => {
    const existing = approvals.find(a => a.mrId === user.id && a.hospitalId === hospitalId);
    if (existing && existing.status !== 'rejected') return;

    const newApproval: MRHospitalApproval = {
      id: 'apprv-' + Math.random().toString(36).substr(2, 9),
      mrId: user.id,
      hospitalId,
      status: 'pending',
      updatedAt: new Date().toISOString()
    };

    const updated = existing 
      ? approvals.map(a => a.id === existing.id ? newApproval : a)
      : [...approvals, newApproval];

    storageService.saveApprovals(updated);
    refreshData();
    showFeedback("Access request sent to hospital admin.");
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  const availableHospitals: Hospital[] = hospitals.filter(h => h.isActive && 
    !approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  ).filter(h => h.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const activePassesToday = passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]);

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> My Profile</button>
      </div>

      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Analyzing your profile and calculating your ranking factors..."}</p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <Building2 className="h-5 w-5 text-indigo-500" /> Authorized Hospitals
            </h3>
            <div className="grid gap-6 sm:grid-cols-2">
              {approvedHospitals.map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-shadow group">
                  <div className="mb-4">
                    <p className="font-bold text-slate-800 text-lg group-hover:text-indigo-600 transition-colors">{h.name}</p>
                  </div>
                  <div className="space-y-3">
                    {h.supportedSessions.map(sess => {
                      const open = isSessionWindowOpen(h, sess);
                      const window = h.sessionWindows?.[sess];
                      return (
                        <div key={sess} className="space-y-1">
                          <button
                            disabled={!open || loading}
                            onClick={() => handleApply(h.id, sess)}
                            className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all group/btn ${
                              open 
                                ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' 
                                : 'bg-slate-200/50 text-slate-400 cursor-not-allowed grayscale'
                            }`}
                          >
                            <span className="flex items-center gap-2">
                              {sess === 'MORNING' ? <Sun className="h-4 w-4" /> : sess === 'EVENING' ? <Moon className="h-4 w-4" /> : <Maximize className="h-4 w-4" />}
                              {sess}
                            </span>
                            <span className="flex items-center gap-1">
                              {open ? 'APPLY NOW' : 'CLOSED'}
                              {open && <PlusCircle className="h-3 w-3 group-hover/btn:scale-125 transition-transform" />}
                            </span>
                          </button>
                          <div className="flex justify-between px-1 text-[9px] font-bold text-slate-400">
                            <span className="uppercase tracking-tighter">Window: {window?.start} - {window?.end}</span>
                            {open && <span className="text-green-500 animate-pulse">LIVE</span>}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
              {approvedHospitals.length === 0 && (
                <div className="sm:col-span-2 p-12 text-center bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl">
                  <Building2 className="h-8 w-8 text-slate-300 mx-auto mb-4 opacity-30" />
                  <p className="text-sm font-medium text-slate-500">No hospital access yet.</p>
                  <button onClick={() => setActiveTab('directory')} className="text-xs text-indigo-600 font-bold mt-2 hover:underline underline-offset-4 tracking-tight">Browse Hospital Directory →</button>
                </div>
              )}
            </div>
          </section>

          <section className="space-y-6">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <h3 className="text-lg font-bold mb-6 flex items-center justify-between gap-2 text-slate-800">
                <span className="flex items-center gap-2"><QrCode className="h-5 w-5 text-indigo-500" /> My Passes</span>
                {activePassesToday.length > 0 && (
                  <button 
                    onClick={startScanner}
                    className="flex items-center gap-1.5 bg-indigo-600 text-white px-3 py-1.5 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 transition-all shadow-md active:scale-95 animate-bounce"
                  >
                    <Camera className="h-3.5 w-3.5" /> Scan Gate QR
                  </button>
                )}
              </h3>
              <div className="space-y-4">
                {activePassesToday.map(p => (
                  <div key={p.id} className="p-4 bg-indigo-50 border-2 border-indigo-100 rounded-2xl shadow-sm">
                    <div className="flex justify-between items-center mb-3">
                       <div className="flex items-center gap-1.5">
                        {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : p.session === 'EVENING' ? <Moon className="h-3 w-3 text-indigo-400" /> : <Maximize className="h-3 w-3 text-indigo-500" />}
                        <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">{p.session}</span>
                       </div>
                      <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded shadow-xs">{p.passDate}</span>
                    </div>
                    <p className="font-bold text-slate-800 text-sm mb-4 leading-tight">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                    <div className="bg-white p-4 rounded-xl border border-indigo-100 flex items-center justify-between shadow-inner">
                       <div>
                          <p className="text-[9px] font-black text-slate-400 uppercase">Time Slot</p>
                          <p className="text-xs font-black text-slate-700">{p.timeSlot}</p>
                       </div>
                       <div className="flex flex-col items-end">
                          <p className="text-[9px] font-black text-slate-400 uppercase">Pass ID</p>
                          <p className="text-xs font-black text-indigo-600 font-mono">{p.id}</p>
                       </div>
                    </div>
                  </div>
                ))}
                {activePassesToday.length === 0 && (
                  <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-2xl">
                    <p className="text-xs italic">No active passes for today.</p>
                    <p className="text-[10px] mt-1">Select a session on the left to apply.</p>
                  </div>
                )}
              </div>
            </div>

            {activePassesToday.length > 0 && (
              <div className="bg-amber-50 p-6 rounded-3xl border border-amber-100">
                 <div className="flex items-center gap-2 mb-3">
                    <ShieldCheck className="h-5 w-5 text-amber-500" />
                    <h4 className="text-xs font-black text-amber-800 uppercase tracking-widest">Entry Instructions</h4>
                 </div>
                 <ol className="space-y-3">
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">1</span>
                       Arrive at the gate during your slot.
                    </li>
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">2</span>
                       Locate the permanent Gate QR sign.
                    </li>
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">3</span>
                       Click 'Scan Gate QR' above to validate entry.
                    </li>
                 </ol>
              </div>
            )}
          </section>
        </div>
      )}

      {/* Camera Scanner Modal */}
      {isScanning && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="w-full max-w-md relative flex flex-col items-center">
              <button onClick={stopScanner} className="absolute -top-16 right-0 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all">
                <X className="h-6 w-6" />
              </button>

              <div className="w-full aspect-square bg-black rounded-[3rem] border-4 border-white/20 overflow-hidden relative shadow-2xl">
                 <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />

                 {/* Scanner Overlay UI */}
                 <div className="absolute inset-0 flex items-center justify-center">
                    <div className="w-64 h-64 border-2 border-indigo-400 rounded-3xl relative">
                       <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-indigo-500"></div>
                       <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-indigo-500"></div>
                       <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-indigo-500"></div>
                       <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-indigo-500"></div>
                       <div className="w-full h-0.5 bg-indigo-500/50 absolute top-1/2 -translate-y-1/2 animate-pulse shadow-[0_0_15px_rgba(99,102,241,0.5)]"></div>
                    </div>
                 </div>
              </div>

              <div className="mt-8 text-center space-y-4">
                 <div className="flex items-center gap-3 justify-center">
                    <Smartphone className="h-6 w-6 text-indigo-400" />
                    <h3 className="text-xl font-black text-white">Align with Gate QR</h3>
                 </div>
                 <p className="text-indigo-200/60 text-xs font-bold uppercase tracking-widest">Scanning in progress...</p>

                 <div className="pt-8">
                    <button 
                      onClick={() => simulateScan()} 
                      className="px-6 py-3 bg-indigo-600 text-white rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all flex items-center gap-2 mx-auto"
                    >
                       SIMULATE DETECTION <Zap className="h-3.5 w-3.5" />
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'directory' && (
        <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 animate-in fade-in duration-300">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
              <Search className="h-5 w-5 text-indigo-500" /> Hospital Directory
            </h3>
            <div className="relative max-w-md w-full">
              <input 
                type="text" 
                placeholder="Search hospitals..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-medium"
              />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            </div>
          </div>

          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {availableHospitals.map(h => {
              const approval = approvals.find(a => a.mrId === user.id && a.hospitalId === h.id);
              const isPending = approval?.status === 'pending';
              const isRejected = approval?.status === 'rejected';

              return (
                <div key={h.id} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl hover:border-indigo-200 transition-all flex flex-col justify-between">
                  <div>
                    <h4 className="font-bold text-slate-800 mb-1">{h.name}</h4>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight flex items-center gap-1 mb-4"><MapPin className="h-3 w-3" /> {h.address || 'Colombo, Sri Lanka'}</p>
                  </div>

                  {isPending ? (
                    <div className="flex items-center justify-center gap-2 py-3 bg-amber-50 text-amber-600 rounded-xl text-xs font-black uppercase">
                       <Clock className="h-4 w-4" /> Pending Approval
                    </div>
                  ) : isRejected ? (
                    <div className="flex flex-col gap-2">
                       <div className="flex items-center justify-center gap-2 py-3 bg-red-50 text-red-600 rounded-xl text-xs font-black uppercase">
                          <XCircle className="h-4 w-4" /> Request Denied
                       </div>
                       <button onClick={() => requestApproval(h.id)} className="text-[10px] font-bold text-indigo-600 underline">Try Requesting Again</button>
                    </div>
                  ) : (
                    <button 
                      onClick={() => requestApproval(h.id)}
                      className="w-full py-3 bg-white border border-indigo-200 text-indigo-600 font-black rounded-xl text-xs hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                    >
                      REQUEST ACCESS
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </section>
      )}

      {activeTab === 'profile' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm animate-in slide-in-from-bottom-4 duration-500 max-w-2xl mx-auto">
          <div className="flex flex-col items-center mb-8">
            <div className="w-24 h-24 bg-indigo-100 rounded-full flex items-center justify-center mb-4 border-4 border-white shadow-lg">
               <UserCircle className="h-12 w-12 text-indigo-600" />
            </div>
            <h3 className="text-2xl font-black text-slate-800">{user.fullName}</h3>
            <p className="text-indigo-600 font-bold uppercase tracking-widest text-xs mt-1">{user.companyName}</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Login User ID</label>
               <p className="font-bold text-slate-700 font-mono">{user.loginId}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">SLCPI Number</label>
               <p className="font-bold text-slate-700">{user.slcpiId || 'Not registered'}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Mobile Access</label>
               <p className="font-bold text-slate-700">{user.mobileNumber}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">System Join Date</label>
               <p className="font-bold text-slate-700">{new Date(user.createdAt).toLocaleDateString()}</p>
            </div>
          </div>

          <div className="mt-8 pt-8 border-t border-slate-100">
             <div className="flex items-center gap-3 p-4 bg-indigo-50 rounded-2xl border border-indigo-100">
                <ShieldCheck className="h-5 w-5 text-indigo-500" />
                <p className="text-xs font-bold text-indigo-900 leading-tight">Your compliance documents are verified and managed by your company administrator.</p>
             </div>
          </div>
        </section>
      )}
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, ChevronRight, MapPin, XCircle, Camera, X, Smartphone, Zap
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');

  // Scanner States
  const [isScanning, setIsScanning] = useState(false);
  const [stream, setStream] = useState<MediaStream | null>(null);

  useEffect(() => { refreshData(); }, []);

  // Effect to handle video stream attachment after modal renders
  useEffect(() => {
    if (isScanning && stream && videoRef.current) {
      videoRef.current.srcObject = stream;
      videoRef.current.play().catch(e => console.error("Video play error:", e));
    }
  }, [isScanning, stream]);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);

    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const startScanner = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      setStream(s);
      setIsScanning(true);
    } catch (err) {
      console.error("Scanner access error:", err);
      showFeedback("Could not access camera. Check permissions.", "error");
    }
  };

  const stopScanner = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
    setIsScanning(false);
  };

  const simulateScan = (simulatedValue?: string) => {
    const qrValue = simulatedValue || prompt("Simulate Scan: Please enter the Gate QR Identifier (e.g. MEDPASS-GATE-h1)");
    if (!qrValue) return;

    if (!qrValue.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid Gate QR Code detected.", "error");
      return;
    }

    const hospitalId = qrValue.replace('MEDPASS-GATE-', '');
    const today = new Date().toISOString().split('T')[0];

    const activePass = passes.find(p => 
      p.hospitalId === hospitalId && 
      p.passDate === today && 
      p.entryStatus === 'not_entered'
    );

    if (!activePass) {
      showFeedback("No active pass found for this hospital today.", "error");
      return;
    }

    const allPasses = storageService.getPasses();
    const updatedPasses = allPasses.map(p => 
      p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p
    );

    const log = {
      id: Math.random().toString(36).substr(2, 9),
      issuedPassId: activePass.id,
      entryTime: new Date().toISOString(),
      verifiedBy: 'Self-Gate-Scan'
    };

    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...storageService.getLogs(), log]);

    stopScanner();
    refreshData();
    showFeedback("Entry Validated! You may proceed to the gate.", 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[sess];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');

    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { showFeedback(reason || "Ineligible", 'error'); return; }

    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Application already submitted for this session today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      showFeedback("Pass application submitted successfully!");
    }, 600);
  };

  const requestApproval = (hospitalId: string) => {
    const existing = approvals.find(a => a.mrId === user.id && a.hospitalId === hospitalId);
    if (existing && existing.status !== 'rejected') return;

    const newApproval: MRHospitalApproval = {
      id: 'apprv-' + Math.random().toString(36).substr(2, 9),
      mrId: user.id,
      hospitalId,
      status: 'pending',
      updatedAt: new Date().toISOString()
    };

    const updated = existing 
      ? approvals.map(a => a.id === existing.id ? newApproval : a)
      : [...approvals, newApproval];

    storageService.saveApprovals(updated);
    refreshData();
    showFeedback("Access request sent to hospital admin.");
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  const availableHospitals: Hospital[] = hospitals.filter(h => h.isActive && 
    !approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  ).filter(h => h.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const activePassesToday = passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]);

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> My Profile</button>
      </div>

      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Analyzing your profile and calculating your ranking factors..."}</p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <Building2 className="h-5 w-5 text-indigo-500" /> Authorized Hospitals
            </h3>
            <div className="grid gap-6 sm:grid-cols-2">
              {approvedHospitals.map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-shadow group">
                  <div className="mb-4">
                    <p className="font-bold text-slate-800 text-lg group-hover:text-indigo-600 transition-colors">{h.name}</p>
                  </div>
                  <div className="space-y-3">
                    {h.supportedSessions.map(sess => {
                      const open = isSessionWindowOpen(h, sess);
                      const window = h.sessionWindows?.[sess];
                      return (
                        <div key={sess} className="space-y-1">
                          <button
                            disabled={!open || loading}
                            onClick={() => handleApply(h.id, sess)}
                            className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all group/btn ${
                              open 
                                ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' 
                                : 'bg-slate-200/50 text-slate-400 cursor-not-allowed grayscale'
                            }`}
                          >
                            <span className="flex items-center gap-2">
                              {sess === 'MORNING' ? <Sun className="h-4 w-4" /> : sess === 'EVENING' ? <Moon className="h-4 w-4" /> : <Maximize className="h-4 w-4" />}
                              {sess}
                            </span>
                            <span className="flex items-center gap-1">
                              {open ? 'APPLY NOW' : 'CLOSED'}
                              {open && <PlusCircle className="h-3 w-3 group-hover/btn:scale-125 transition-transform" />}
                            </span>
                          </button>
                          <div className="flex justify-between px-1 text-[9px] font-bold text-slate-400">
                            <span className="uppercase tracking-tighter">Window: {window?.start} - {window?.end}</span>
                            {open && <span className="text-green-500 animate-pulse">LIVE</span>}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
              {approvedHospitals.length === 0 && (
                <div className="sm:col-span-2 p-12 text-center bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl">
                  <Building2 className="h-8 w-8 text-slate-300 mx-auto mb-4 opacity-30" />
                  <p className="text-sm font-medium text-slate-500">No hospital access yet.</p>
                  <button onClick={() => setActiveTab('directory')} className="text-xs text-indigo-600 font-bold mt-2 hover:underline underline-offset-4 tracking-tight">Browse Hospital Directory →</button>
                </div>
              )}
            </div>
          </section>

          <section className="space-y-6">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <h3 className="text-lg font-bold mb-6 flex items-center justify-between gap-2 text-slate-800">
                <span className="flex items-center gap-2"><QrCode className="h-5 w-5 text-indigo-500" /> My Passes</span>
                {activePassesToday.length > 0 && (
                  <button 
                    onClick={startScanner}
                    className="flex items-center gap-1.5 bg-indigo-600 text-white px-3 py-1.5 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 transition-all shadow-md active:scale-95 animate-bounce"
                  >
                    <Camera className="h-3.5 w-3.5" /> Scan Gate QR
                  </button>
                )}
              </h3>
              <div className="space-y-4">
                {activePassesToday.map(p => (
                  <div key={p.id} className="p-4 bg-indigo-50 border-2 border-indigo-100 rounded-2xl shadow-sm">
                    <div className="flex justify-between items-center mb-3">
                       <div className="flex items-center gap-1.5">
                        {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : p.session === 'EVENING' ? <Moon className="h-3 w-3 text-indigo-400" /> : <Maximize className="h-3 w-3 text-indigo-500" />}
                        <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">{p.session}</span>
                       </div>
                      <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded shadow-xs">{p.passDate}</span>
                    </div>
                    <p className="font-bold text-slate-800 text-sm mb-4 leading-tight">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                    <div className="bg-white p-4 rounded-xl border border-indigo-100 flex items-center justify-between shadow-inner">
                       <div>
                          <p className="text-[9px] font-black text-slate-400 uppercase">Time Slot</p>
                          <p className="text-xs font-black text-slate-700">{p.timeSlot}</p>
                       </div>
                       <div className="flex flex-col items-end">
                          <p className="text-[9px] font-black text-slate-400 uppercase">Pass ID</p>
                          <p className="text-xs font-black text-indigo-600 font-mono">{p.id}</p>
                       </div>
                    </div>
                  </div>
                ))}
                {activePassesToday.length === 0 && (
                  <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-2xl">
                    <p className="text-xs italic">No active passes for today.</p>
                    <p className="text-[10px] mt-1">Select a session on the left to apply.</p>
                  </div>
                )}
              </div>
            </div>

            {activePassesToday.length > 0 && (
              <div className="bg-amber-50 p-6 rounded-3xl border border-amber-100">
                 <div className="flex items-center gap-2 mb-3">
                    <ShieldCheck className="h-5 w-5 text-amber-500" />
                    <h4 className="text-xs font-black text-amber-800 uppercase tracking-widest">Entry Instructions</h4>
                 </div>
                 <ol className="space-y-3">
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">1</span>
                       Arrive at the gate during your slot.
                    </li>
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">2</span>
                       Locate the permanent Gate QR sign.
                    </li>
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">3</span>
                       Click 'Scan Gate QR' above to validate entry.
                    </li>
                 </ol>
              </div>
            )}
          </section>
        </div>
      )}

      {/* Camera Scanner Modal */}
      {isScanning && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="w-full max-w-md relative flex flex-col items-center">
              <button onClick={stopScanner} className="absolute -top-16 right-0 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all">
                <X className="h-6 w-6" />
              </button>

              <div className="w-full aspect-square bg-black rounded-[3rem] border-4 border-white/20 overflow-hidden relative shadow-2xl">
                 <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover" />

                 {/* Scanner Overlay UI */}
                 <div className="absolute inset-0 flex items-center justify-center">
                    <div className="w-64 h-64 border-2 border-indigo-400 rounded-3xl relative">
                       <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-indigo-500"></div>
                       <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-indigo-500"></div>
                       <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-indigo-500"></div>
                       <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-indigo-500"></div>
                       <div className="w-full h-0.5 bg-indigo-500/50 absolute top-1/2 -translate-y-1/2 animate-pulse shadow-[0_0_15px_rgba(99,102,241,0.5)]"></div>
                    </div>
                 </div>
              </div>

              <div className="mt-8 text-center space-y-4">
                 <div className="flex items-center gap-3 justify-center">
                    <Smartphone className="h-6 w-6 text-indigo-400" />
                    <h3 className="text-xl font-black text-white">Align with Gate QR</h3>
                 </div>
                 <p className="text-indigo-200/60 text-xs font-bold uppercase tracking-widest">Scanning in progress...</p>

                 <div className="pt-8">
                    <button 
                      onClick={() => simulateScan()} 
                      className="px-6 py-3 bg-indigo-600 text-white rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all flex items-center gap-2 mx-auto"
                    >
                       SIMULATE DETECTION <Zap className="h-3.5 w-3.5" />
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'directory' && (
        <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 animate-in fade-in duration-300">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
              <Search className="h-5 w-5 text-indigo-500" /> Hospital Directory
            </h3>
            <div className="relative max-w-md w-full">
              <input 
                type="text" 
                placeholder="Search hospitals..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-medium"
              />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            </div>
          </div>

          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {availableHospitals.map(h => {
              const approval = approvals.find(a => a.mrId === user.id && a.hospitalId === h.id);
              const isPending = approval?.status === 'pending';
              const isRejected = approval?.status === 'rejected';

              return (
                <div key={h.id} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl hover:border-indigo-200 transition-all flex flex-col justify-between">
                  <div>
                    <h4 className="font-bold text-slate-800 mb-1">{h.name}</h4>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight flex items-center gap-1 mb-4"><MapPin className="h-3 w-3" /> {h.address || 'Colombo, Sri Lanka'}</p>
                  </div>

                  {isPending ? (
                    <div className="flex items-center justify-center gap-2 py-3 bg-amber-50 text-amber-600 rounded-xl text-xs font-black uppercase">
                       <Clock className="h-4 w-4" /> Pending Approval
                    </div>
                  ) : isRejected ? (
                    <div className="flex flex-col gap-2">
                       <div className="flex items-center justify-center gap-2 py-3 bg-red-50 text-red-600 rounded-xl text-xs font-black uppercase">
                          <XCircle className="h-4 w-4" /> Request Denied
                       </div>
                       <button onClick={() => requestApproval(h.id)} className="text-[10px] font-bold text-indigo-600 underline">Try Requesting Again</button>
                    </div>
                  ) : (
                    <button 
                      onClick={() => requestApproval(h.id)}
                      className="w-full py-3 bg-white border border-indigo-200 text-indigo-600 font-black rounded-xl text-xs hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                    >
                      REQUEST ACCESS
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </section>
      )}

      {activeTab === 'profile' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm animate-in slide-in-from-bottom-4 duration-500 max-w-2xl mx-auto">
          <div className="flex flex-col items-center mb-8">
            <div className="w-24 h-24 bg-indigo-100 rounded-full flex items-center justify-center mb-4 border-4 border-white shadow-lg">
               <UserCircle className="h-12 w-12 text-indigo-600" />
            </div>
            <h3 className="text-2xl font-black text-slate-800">{user.fullName}</h3>
            <p className="text-indigo-600 font-bold uppercase tracking-widest text-xs mt-1">{user.companyName}</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Login User ID</label>
               <p className="font-bold text-slate-700 font-mono">{user.loginId}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">SLCPI Number</label>
               <p className="font-bold text-slate-700">{user.slcpiId || 'Not registered'}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Mobile Access</label>
               <p className="font-bold text-slate-700">{user.mobileNumber}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">System Join Date</label>
               <p className="font-bold text-slate-700">{new Date(user.createdAt).toLocaleDateString()}</p>
            </div>
          </div>

          <div className="mt-8 pt-8 border-t border-slate-100">
             <div className="flex items-center gap-3 p-4 bg-indigo-50 rounded-2xl border border-indigo-100">
                <ShieldCheck className="h-5 w-5 text-indigo-500" />
                <p className="text-xs font-bold text-indigo-900 leading-tight">Your compliance documents are verified and managed by your company administrator.</p>
             </div>
          </div>
        </section>
      )}
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, ChevronRight, MapPin, XCircle, Camera, X, Smartphone, Zap
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const videoRef = useRef<HTMLVideoElement>(null);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');

  // Scanner States
  const [isScanning, setIsScanning] = useState(false);
  const [stream, setStream] = useState<MediaStream | null>(null);

  useEffect(() => { refreshData(); }, []);

  // Effect to handle video stream attachment after modal renders
  useEffect(() => {
    if (isScanning && stream && videoRef.current) {
      videoRef.current.srcObject = stream;
      videoRef.current.play().catch(e => console.error("Video play error:", e));
    }
  }, [isScanning, stream]);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);

    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const startScanner = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      setStream(s);
      setIsScanning(true);
    } catch (err) {
      console.error("Scanner access error:", err);
      showFeedback("Could not access camera. Check permissions.", "error");
    }
  };

  const stopScanner = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
    setIsScanning(false);
  };

  const simulateScan = (simulatedValue?: string) => {
    const qrValue = simulatedValue || prompt("Simulate Scan: Please enter the Gate QR Identifier (e.g. MEDPASS-GATE-h1)");
    if (!qrValue) return;

    if (!qrValue.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid Gate QR Code detected.", "error");
      return;
    }

    const hospitalId = qrValue.replace('MEDPASS-GATE-', '');
    const today = new Date().toISOString().split('T')[0];

    const activePass = passes.find(p => 
      p.hospitalId === hospitalId && 
      p.passDate === today && 
      p.entryStatus === 'not_entered'
    );

    if (!activePass) {
      showFeedback("No active pass found for this hospital today.", "error");
      return;
    }

    const allPasses = storageService.getPasses();
    const updatedPasses = allPasses.map(p => 
      p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p
    );

    const log = {
      id: Math.random().toString(36).substr(2, 9),
      issuedPassId: activePass.id,
      entryTime: new Date().toISOString(),
      verifiedBy: 'Self-Gate-Scan'
    };

    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...storageService.getLogs(), log]);

    stopScanner();
    refreshData();
    showFeedback("Entry Validated! You may proceed to the gate.", 'success');
  };

  // Fixed the error where 'sess' was used instead of 'session'
  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');

    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { showFeedback(reason || "Ineligible", 'error'); return; }

    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Application already submitted for this session today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      showFeedback("Pass application submitted successfully!");
    }, 600);
  };

  const requestApproval = (hospitalId: string) => {
    const existing = approvals.find(a => a.mrId === user.id && a.hospitalId === hospitalId);
    if (existing && existing.status !== 'rejected') return;

    const newApproval: MRHospitalApproval = {
      id: 'apprv-' + Math.random().toString(36).substr(2, 9),
      mrId: user.id,
      hospitalId,
      status: 'pending',
      updatedAt: new Date().toISOString()
    };

    const updated = existing 
      ? approvals.map(a => a.id === existing.id ? newApproval : a)
      : [...approvals, newApproval];

    storageService.saveApprovals(updated);
    refreshData();
    showFeedback("Access request sent to hospital admin.");
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  const availableHospitals: Hospital[] = hospitals.filter(h => h.isActive && 
    !approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  ).filter(h => h.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const activePassesToday = passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]);

