                     </div>
                     <div>
                        <p className="font-black text-slate-800 leading-tight">{mr?.fullName || 'Unknown MR'}</p>
                        <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-tight">{mr?.companyName || 'Visitor'}</p>
                     </div>
                  </div>
                  <div className="text-right">
                     <div className="flex items-center justify-end gap-1.5 text-slate-800 font-black text-sm">
                        <Clock className="h-3 w-3 text-slate-300" />
                        {new Date(log.entryTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                     </div>
                     <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Pass: {log.issuedPassId}</p>
                  </div>
               </div>
             );
           })}

           {logs.length === 0 && (
             <div className="h-full flex flex-col items-center justify-center py-20 text-slate-300">
                <Users className="h-16 w-16 mb-4 opacity-10" />
                <p className="text-sm font-bold uppercase tracking-widest">Waiting for entries...</p>
                <p className="text-[10px] mt-1 italic">Entries will appear here as soon as MRs scan the gate QR.</p>
             </div>
           )}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 text-center">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Validated Today: {logs.length}</p>
        </div>
      </section>
    </div>
  );
};

export default SecurityView;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, ChevronRight, MapPin, XCircle, Camera, X, Smartphone, Zap
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

/**
 * Dedicated Scanner Component to handle its own lifecycle and video ref
 */
const QRScannerModal: React.FC<{
  onClose: () => void;
  onScan: (value: string) => void;
  mrId: string;
}> = ({ onClose, onScan, mrId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let activeStream: MediaStream | null = null;

    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' } 
        });
        activeStream = s;
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
          setTimeout(() => {
            videoRef.current?.play().catch(console.error);
          }, 150);
        }
      } catch (err) {
        console.error("Camera access error:", err);
        setError("Could not access camera. Please check permissions.");
      }
    }

    setupCamera();

    return () => {
      if (activeStream) {
        activeStream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const handleSimulateAuto = () => {
    // Attempt to automatically find a pass to simulate success
    const currentPasses = storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    const myPassesToday = currentPasses.filter(p => 
      p.mrId === mrId && 
      p.passDate === today && 
      p.entryStatus === 'not_entered'
    );

    if (myPassesToday.length > 0) {
      onScan(`MEDPASS-GATE-${myPassesToday[0].hospitalId}`);
    } else {
      onScan(""); // Trigger the manual prompt fallback
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="w-full max-w-md relative flex flex-col items-center">
        <button 
          onClick={onClose} 
          className="absolute -top-16 right-0 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all active:scale-90"
        >
          <X className="h-6 w-6" />
        </button>

        <div className="w-full aspect-square bg-black rounded-[3rem] border-4 border-white/20 overflow-hidden relative shadow-2xl ring-4 ring-indigo-500/20">
          {error ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center">
              <AlertCircle className="h-12 w-12 text-red-500 mb-4" />
              <p className="text-white font-bold">{error}</p>
            </div>
          ) : (
            <>
              <video 
                ref={videoRef} 
                autoPlay 
                playsInline 
                muted 
                className="w-full h-full object-cover" 
              />
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-64 h-64 border-2 border-indigo-400/50 rounded-3xl relative">
                  <div className="absolute top-0 left-0 w-10 h-10 border-t-4 border-l-4 border-indigo-500 rounded-tl-lg"></div>
                  <div className="absolute top-0 right-0 w-10 h-10 border-t-4 border-r-4 border-indigo-500 rounded-tr-lg"></div>
                  <div className="absolute bottom-0 left-0 w-10 h-10 border-b-4 border-l-4 border-indigo-500 rounded-bl-lg"></div>
                  <div className="absolute bottom-0 right-0 w-10 h-10 border-b-4 border-r-4 border-indigo-500 rounded-br-lg"></div>
                  <div className="w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent absolute top-0 animate-[scan_2s_ease-in-out_infinite] shadow-[0_0_15px_rgba(99,102,241,0.8)]"></div>
                </div>
              </div>
            </>
          )}
        </div>

        <div className="mt-8 text-center space-y-4">
          <div className="flex items-center gap-3 justify-center">
            <Smartphone className="h-6 w-6 text-indigo-400" />
            <h3 className="text-xl font-black text-white">Align with Gate QR</h3>
          </div>
          <p className="text-indigo-200/60 text-[10px] font-black uppercase tracking-[0.2em]">Lens active • Looking for security code</p>

          <div className="pt-8">
            <button 
              onClick={handleSimulateAuto} 
              className="px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all flex items-center gap-3 mx-auto shadow-xl shadow-indigo-900/40 active:scale-95"
            >
              SIMULATE GATE DETECTION <Zap className="h-4 w-4" />
            </button>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes scan {
          0%, 100% { top: 0%; opacity: 0.5; }
          50% { top: 100%; opacity: 1; }
        }
      `}</style>
    </div>
  );
};

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);

    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const handleScanDetected = (qrValueInput?: string) => {
    // Always fetch freshest data from storage to avoid session/state lag
    const latestPasses = storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA'); // Local date YYYY-MM-DD

    let qrValue = qrValueInput;

    // If no value (cancelled simulate prompt or clicked button), ask for manual entry
    if (!qrValue) {
       qrValue = prompt("Please enter the Gate Identifier shown on the security screen (e.g. MEDPASS-GATE-h1):");
    }

    if (!qrValue || !qrValue.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid scan format. Please try again.", "error");
      return;
    }

    const hospitalId = qrValue.replace('MEDPASS-GATE-', '');

    // Find the correct active pass specifically for THIS MR, THIS hospital, and TODAY
    const activePass = latestPasses.find(p => 
      p.mrId === user.id &&
      p.hospitalId === hospitalId && 
      p.passDate === today && 
      p.entryStatus === 'not_entered'
    );

    if (!activePass) {
      showFeedback(`No active pass found for ${hospitals.find(h => h.id === hospitalId)?.name || 'this hospital'} today.`, "error");
      return;
    }

    // Process entry in storage
    const updatedPasses = latestPasses.map(p => 
      p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p
    );

    const log = {
      id: Math.random().toString(36).substr(2, 9),
      issuedPassId: activePass.id,
      entryTime: new Date().toISOString(),
      verifiedBy: 'Self-Gate-Scanner'
    };

    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...storageService.getLogs(), log]);

    setIsScanning(false);
    refreshData();
    showFeedback("Access Granted! Gate security has been notified.", 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');

    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { showFeedback(reason || "Ineligible", 'error'); return; }

    const todayStr = new Date().toLocaleDateString('en-CA');
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Application already submitted for this session today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      showFeedback("Pass application submitted successfully!");
    }, 600);
  };

  const requestApproval = (hospitalId: string) => {
    const existing = approvals.find(a => a.mrId === user.id && a.hospitalId === hospitalId);
    if (existing && existing.status !== 'rejected') return;

    const newApproval: MRHospitalApproval = {
      id: 'apprv-' + Math.random().toString(36).substr(2, 9),
      mrId: user.id,
      hospitalId,
      status: 'pending',
      updatedAt: new Date().toISOString()
    };

    const updated = existing 
      ? approvals.map(a => a.id === existing.id ? newApproval : a)
      : [...approvals, newApproval];

    storageService.saveApprovals(updated);
    refreshData();
    showFeedback("Access request sent to hospital admin.");
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  const availableHospitals: Hospital[] = hospitals.filter(h => h.isActive && 
    !approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  ).filter(h => h.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const activePassesToday = passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toLocaleDateString('en-CA'));

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> My Profile</button>
      </div>

      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Analyzing your profile and calculating your ranking factors..."}</p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
              <Building2 className="h-5 w-5 text-indigo-500" /> Authorized Hospitals
            </h3>
            <div className="grid gap-6 sm:grid-cols-2">
              {approvedHospitals.map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-shadow group">
                  <div className="mb-4">
                    <p className="font-bold text-slate-800 text-lg group-hover:text-indigo-600 transition-colors">{h.name}</p>
                  </div>
                  <div className="space-y-3">
                    {h.supportedSessions.map(sess => {
                      const open = isSessionWindowOpen(h, sess);
                      const window = h.sessionWindows?.[sess];
                      return (
                        <div key={sess} className="space-y-1">
                          <button
                            disabled={!open || loading}
                            onClick={() => handleApply(h.id, sess)}
                            className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all group/btn ${
                              open 
                                ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' 
                                : 'bg-slate-200/50 text-slate-400 cursor-not-allowed grayscale'
                            }`}
                          >
                            <span className="flex items-center gap-2">
                              {sess === 'MORNING' ? <Sun className="h-4 w-4" /> : sess === 'EVENING' ? <Moon className="h-4 w-4" /> : <Maximize className="h-4 w-4" />}
                              {sess}
                            </span>
                            <span className="flex items-center gap-1">
                              {open ? 'APPLY NOW' : 'CLOSED'}
                              {open && <PlusCircle className="h-3 w-3 group-hover/btn:scale-125 transition-transform" />}
                            </span>
                          </button>
                          <div className="flex justify-between px-1 text-[9px] font-bold text-slate-400">
                            <span className="uppercase tracking-tighter">Window: {window?.start} - {window?.end}</span>
                            {open && <span className="text-green-500 animate-pulse">LIVE</span>}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
              {approvedHospitals.length === 0 && (
                <div className="sm:col-span-2 p-12 text-center bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl">
                  <Building2 className="h-8 w-8 text-slate-300 mx-auto mb-4 opacity-30" />
                  <p className="text-sm font-medium text-slate-500">No hospital access yet.</p>
                  <button onClick={() => setActiveTab('directory')} className="text-xs text-indigo-600 font-bold mt-2 hover:underline underline-offset-4 tracking-tight">Browse Hospital Directory →</button>
                </div>
              )}
            </div>
          </section>

          <section className="space-y-6">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <h3 className="text-lg font-bold mb-6 flex items-center justify-between gap-2 text-slate-800">
                <span className="flex items-center gap-2"><QrCode className="h-5 w-5 text-indigo-500" /> My Passes</span>
                {activePassesToday.length > 0 && (
                  <button 
                    onClick={() => setIsScanning(true)}
                    className="flex items-center gap-1.5 bg-indigo-600 text-white px-3 py-1.5 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 transition-all shadow-md active:scale-95 animate-bounce"
                  >
                    <Camera className="h-3.5 w-3.5" /> Scan Gate QR
                  </button>
                )}
              </h3>
              <div className="space-y-4">
                {activePassesToday.map(p => (
                  <div key={p.id} className="p-4 bg-indigo-50 border-2 border-indigo-100 rounded-2xl shadow-sm">
                    <div className="flex justify-between items-center mb-3">
                       <div className="flex items-center gap-1.5">
                        {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : p.session === 'EVENING' ? <Moon className="h-3 w-3 text-indigo-400" /> : <Maximize className="h-3 w-3 text-indigo-500" />}
                        <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">{p.session}</span>
                       </div>
                      <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded shadow-xs">{p.passDate}</span>
                    </div>
                    <p className="font-bold text-slate-800 text-sm mb-4 leading-tight">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                    <div className="bg-white p-4 rounded-xl border border-indigo-100 flex items-center justify-between shadow-inner">
                       <div>
                          <p className="text-[9px] font-black text-slate-400 uppercase">Time Slot</p>
                          <p className="text-xs font-black text-slate-700">{p.timeSlot}</p>
                       </div>
                       <div className="flex flex-col items-end">
                          <p className="text-[9px] font-black text-slate-400 uppercase">Pass ID</p>
                          <p className="text-xs font-black text-indigo-600 font-mono">{p.id}</p>
                       </div>
                    </div>
                  </div>
                ))}
                {activePassesToday.length === 0 && (
                  <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-2xl">
                    <p className="text-xs italic">No active passes for today.</p>
                    <p className="text-[10px] mt-1">Select a session on the left to apply.</p>
                  </div>
                )}
              </div>
            </div>

            {activePassesToday.length > 0 && (
              <div className="bg-amber-50 p-6 rounded-3xl border border-amber-100">
                 <div className="flex items-center gap-2 mb-3">
                    <ShieldCheck className="h-5 w-5 text-amber-500" />
                    <h4 className="text-xs font-black text-amber-800 uppercase tracking-widest">Entry Instructions</h4>
                 </div>
                 <ol className="space-y-3">
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">1</span>
                       Arrive at the gate during your slot.
                    </li>
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">2</span>
                       Locate the permanent Gate QR sign.
                    </li>
                    <li className="text-[11px] font-medium text-amber-900 flex gap-2">
                       <span className="font-black bg-amber-200 w-4 h-4 rounded-full flex items-center justify-center shrink-0">3</span>
                       Click 'Scan Gate QR' above to validate entry.
                    </li>
                 </ol>
              </div>
            )}
          </section>
        </div>
      )}

      {/* QR Scanner Modal (New Robust Component) */}
      {isScanning && (
        <QRScannerModal 
          onClose={() => setIsScanning(false)} 
          onScan={handleScanDetected} 
          mrId={user.id}
        />
      )}

      {activeTab === 'directory' && (
        <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 animate-in fade-in duration-300">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
              <Search className="h-5 w-5 text-indigo-500" /> Hospital Directory
            </h3>
            <div className="relative max-w-md w-full">
              <input 
                type="text" 
                placeholder="Search hospitals..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-medium"
              />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            </div>
          </div>

          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {availableHospitals.map(h => {
              const approval = approvals.find(a => a.mrId === user.id && a.hospitalId === h.id);
              const isPending = approval?.status === 'pending';
              const isRejected = approval?.status === 'rejected';

              return (
                <div key={h.id} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl hover:border-indigo-200 transition-all flex flex-col justify-between">
                  <div>
                    <h4 className="font-bold text-slate-800 mb-1">{h.name}</h4>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight flex items-center gap-1 mb-4"><MapPin className="h-3 w-3" /> {h.address || 'Colombo, Sri Lanka'}</p>
                  </div>

                  {isPending ? (
                    <div className="flex items-center justify-center gap-2 py-3 bg-amber-50 text-amber-600 rounded-xl text-xs font-black uppercase">
                       <Clock className="h-4 w-4" /> Pending Approval
                    </div>
                  ) : isRejected ? (
                    <div className="flex flex-col gap-2">
                       <div className="flex items-center justify-center gap-2 py-3 bg-red-50 text-red-600 rounded-xl text-xs font-black uppercase">
                          <XCircle className="h-4 w-4" /> Request Denied
                       </div>
                       <button onClick={() => requestApproval(h.id)} className="text-[10px] font-bold text-indigo-600 underline">Try Requesting Again</button>
                    </div>
                  ) : (
                    <button 
                      onClick={() => requestApproval(h.id)}
                      className="w-full py-3 bg-white border border-indigo-200 text-indigo-600 font-black rounded-xl text-xs hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                    >
                      REQUEST ACCESS
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        </section>
      )}

      {activeTab === 'profile' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm animate-in slide-in-from-bottom-4 duration-500 max-w-2xl mx-auto">
          <div className="flex flex-col items-center mb-8">
            <div className="w-24 h-24 bg-indigo-100 rounded-full flex items-center justify-center mb-4 border-4 border-white shadow-lg">
               <UserCircle className="h-12 w-12 text-indigo-600" />
            </div>
            <h3 className="text-2xl font-black text-slate-800">{user.fullName}</h3>
            <p className="text-indigo-600 font-bold uppercase tracking-widest text-xs mt-1">{user.companyName}</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Login User ID</label>
               <p className="font-bold text-slate-700 font-mono">{user.loginId}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">SLCPI Number</label>
               <p className="font-bold text-slate-700">{user.slcpiId || 'Not registered'}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Mobile Access</label>
               <p className="font-bold text-slate-700">{user.mobileNumber}</p>
            </div>
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">System Join Date</label>
               <p className="font-bold text-slate-700">{new Date(user.createdAt).toLocaleDateString()}</p>
            </div>
          </div>

          <div className="mt-8 pt-8 border-t border-slate-100">
             <div className="flex items-center gap-3 p-4 bg-indigo-50 rounded-2xl border border-indigo-100">
                <ShieldCheck className="h-5 w-5 text-indigo-500" />
                <p className="text-xs font-bold text-indigo-900 leading-tight">Your compliance documents are verified and managed by your company administrator.</p>
             </div>
          </div>
        </section>
      )}
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, ChevronRight, MapPin, XCircle, Camera, X, Smartphone, Zap, Timer
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

/**
 * Dedicated Scanner Component to handle its own lifecycle and video ref
 */
const QRScannerModal: React.FC<{
  onClose: () => void;
  onScan: (value: string) => void;
  mrId: string;
}> = ({ onClose, onScan, mrId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let activeStream: MediaStream | null = null;

    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' } 
        });
        activeStream = s;
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
          setTimeout(() => {
            videoRef.current?.play().catch(console.error);
          }, 150);
        }
      } catch (err) {
        console.error("Camera access error:", err);
        setError("Could not access camera. Please check permissions.");
      }
    }

    setupCamera();

    return () => {
      if (activeStream) {
        activeStream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const handleSimulateAuto = () => {
    const currentPasses = storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    const myPassesToday = currentPasses.filter(p => 
      p.mrId === mrId && 
      p.passDate === today && 
      p.entryStatus === 'not_entered'
    );

    if (myPassesToday.length > 0) {
      onScan(`MEDPASS-GATE-${myPassesToday[0].hospitalId}`);
    } else {
      onScan(""); // Trigger the manual prompt fallback
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="w-full max-w-md relative flex flex-col items-center">
        <button 
          onClick={onClose} 
          className="absolute -top-16 right-0 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all active:scale-90"
        >
          <X className="h-6 w-6" />
        </button>

        <div className="w-full aspect-square bg-black rounded-[3rem] border-4 border-white/20 overflow-hidden relative shadow-2xl ring-4 ring-indigo-500/20">
          {error ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center">
              <AlertCircle className="h-12 w-12 text-red-500 mb-4" />
              <p className="text-white font-bold">{error}</p>
            </div>
          ) : (
            <>
              <video 
                ref={videoRef} 
                autoPlay 
                playsInline 
                muted 
                className="w-full h-full object-cover" 
              />
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-64 h-64 border-2 border-indigo-400/50 rounded-3xl relative">
                  <div className="absolute top-0 left-0 w-10 h-10 border-t-4 border-l-4 border-indigo-500 rounded-tl-lg"></div>
                  <div className="absolute top-0 right-0 w-10 h-10 border-t-4 border-r-4 border-indigo-500 rounded-tr-lg"></div>
                  <div className="absolute bottom-0 left-0 w-10 h-10 border-b-4 border-l-4 border-indigo-500 rounded-bl-lg"></div>
                  <div className="absolute bottom-0 right-0 w-10 h-10 border-b-4 border-r-4 border-indigo-500 rounded-br-lg"></div>
                  <div className="w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent absolute top-0 animate-[scan_2s_ease-in-out_infinite] shadow-[0_0_15px_rgba(99,102,241,0.8)]"></div>
                </div>
              </div>
            </>
          )}
        </div>

        <div className="mt-8 text-center space-y-4">
          <div className="flex items-center gap-3 justify-center">
            <Smartphone className="h-6 w-6 text-indigo-400" />
            <h3 className="text-xl font-black text-white">Align with Gate QR</h3>
          </div>
          <p className="text-indigo-200/60 text-[10px] font-black uppercase tracking-[0.2em]">Lens active • Looking for security code</p>

          <div className="pt-8">
            <button 
              onClick={handleSimulateAuto} 
              className="px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all flex items-center gap-3 mx-auto shadow-xl shadow-indigo-900/40 active:scale-95"
            >
              SIMULATE GATE DETECTION <Zap className="h-4 w-4" />
            </button>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes scan {
          0%, 100% { top: 0%; opacity: 0.5; }
          50% { top: 100%; opacity: 1; }
        }
      `}</style>
    </div>
  );
};

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);

  // Validation State
  const [validatedPass, setValidatedPass] = useState<IssuedPass | null>(null);
  const [countdown, setCountdown] = useState(60);

  useEffect(() => { refreshData(); }, []);

  // Countdown timer for validated entry
  useEffect(() => {
    let timer: number;
    if (validatedPass && countdown > 0) {
      timer = window.setInterval(() => {
        setCountdown(prev => prev - 1);
      }, 1000);
    } else if (countdown === 0) {
      setValidatedPass(null);
      setCountdown(60);
    }
    return () => clearInterval(timer);
  }, [validatedPass, countdown]);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);

    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const handleScanDetected = (qrValueInput?: string) => {
    const latestPasses = storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');

    let qrValue = qrValueInput;

    if (!qrValue) {
       qrValue = prompt("Please enter the Gate Identifier shown on the security screen (e.g. MEDPASS-GATE-h1):");
    }

    if (!qrValue || !qrValue.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid scan format. Please try again.", "error");
      return;
    }

    const hospitalId = qrValue.replace('MEDPASS-GATE-', '');

    const activePass = latestPasses.find(p => 
      p.mrId === user.id &&
      p.hospitalId === hospitalId && 
      p.passDate === today && 
      p.entryStatus === 'not_entered'
    );

    if (!activePass) {
      showFeedback(`No active pass found for this hospital today.`, "error");
      return;
    }

    const updatedPasses = latestPasses.map(p => 
      p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p
    );

    const log = {
      id: Math.random().toString(36).substr(2, 9),
      issuedPassId: activePass.id,
      entryTime: new Date().toISOString(),
      verifiedBy: 'Self-Gate-Scanner'
    };

    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...storageService.getLogs(), log]);

    setIsScanning(false);
    setValidatedPass(activePass);
    setCountdown(60);
    refreshData();
    showFeedback("Access Granted! Proceed through the gate.", 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');

    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { showFeedback(reason || "Ineligible", 'error'); return; }

    const todayStr = new Date().toLocaleDateString('en-CA');
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Application already submitted for this session today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      showFeedback("Pass application submitted successfully!");
    }, 600);
  };

  const requestApproval = (hospitalId: string) => {
    const existing = approvals.find(a => a.mrId === user.id && a.hospitalId === hospitalId);
    if (existing && existing.status !== 'rejected') return;

    const newApproval: MRHospitalApproval = {
      id: 'apprv-' + Math.random().toString(36).substr(2, 9),
      mrId: user.id,
      hospitalId,
      status: 'pending',
      updatedAt: new Date().toISOString()
    };

    const updated = existing 
      ? approvals.map(a => a.id === existing.id ? newApproval : a)
      : [...approvals, newApproval];

    storageService.saveApprovals(updated);
    refreshData();
    showFeedback("Access request sent to hospital admin.");
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  const availableHospitals: Hospital[] = hospitals.filter(h => h.isActive && 
    !approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  ).filter(h => h.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const todayStr = new Date().toLocaleDateString('en-CA');
  const activePassesToday = passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === todayStr);
  const currentlyVisiting = passes.filter(p => p.entryStatus === 'entered' && p.passDate === todayStr);

  return (
    <div className="space-y-6">
      {/* Post-Scan Approval Screen Overlay */}
      {validatedPass && (
        <div className="fixed inset-0 z-[110] bg-green-600 flex flex-col items-center justify-center p-8 animate-in zoom-in duration-300">
          <div className="w-full max-w-sm text-center">
            <div className="bg-white/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8 animate-pulse">
              <CheckCircle2 className="h-16 w-16 text-white" />
            </div>
            <h2 className="text-4xl font-black text-white mb-2 tracking-tighter">STATUS: APPROVED</h2>
            <p className="text-green-100 font-bold uppercase tracking-widest text-sm mb-12">Access granted • Entry Validated</p>

            <div className="bg-white/10 rounded-[2.5rem] p-10 backdrop-blur-md border border-white/20 shadow-2xl">
              <p className="text-white/60 text-xs font-black uppercase tracking-widest mb-2">Gate Timer Active</p>
              <div className="text-8xl font-black text-white tabular-nums tracking-tighter">
                {countdown}
              </div>
              <p className="text-white/80 text-sm font-bold mt-4">Seconds remaining for entry</p>
            </div>

            <button 
              onClick={() => setValidatedPass(null)}
              className="mt-12 px-8 py-4 bg-white text-green-700 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl active:scale-95 transition-all"
            >
              CLOSE STATUS
            </button>
          </div>
        </div>
      )}

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> My Profile</button>
      </div>

      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Analyzing your profile and calculating your ranking factors..."}</p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
                <Building2 className="h-5 w-5 text-indigo-500" /> Authorized Hospitals
              </h3>
              {currentlyVisiting.length > 0 && (
                <div className="bg-green-100 text-green-700 px-3 py-1.5 rounded-xl text-[10px] font-black uppercase flex items-center gap-2 animate-pulse">
                  <Timer className="h-3 w-3" /> Visiting Now
                </div>
              )}
            </div>

            <div className="grid gap-6 sm:grid-cols-2">
              {approvedHospitals.map(h => (
                <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-shadow group">
                  <div className="mb-4">
                    <p className="font-bold text-slate-800 text-lg group-hover:text-indigo-600 transition-colors">{h.name}</p>
                  </div>
                  <div className="space-y-3">
                    {h.supportedSessions.map(sess => {
                      const open = isSessionWindowOpen(h, sess);
                      const window = h.sessionWindows?.[sess];
                      return (
                        <div key={sess} className="space-y-1">
                          <button
                            disabled={!open || loading}
                            onClick={() => handleApply(h.id, sess)}
                            className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all group/btn ${
                              open 
                                ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' 
                                : 'bg-slate-200/50 text-slate-400 cursor-not-allowed grayscale'
                            }`}
                          >
                            <span className="flex items-center gap-2">
                              {sess === 'MORNING' ? <Sun className="h-4 w-4" /> : sess === 'EVENING' ? <Moon className="h-4 w-4" /> : <Maximize className="h-4 w-4" />}
                              {sess}
                            </span>
                            <span className="flex items-center gap-1">
                              {open ? 'APPLY NOW' : 'CLOSED'}
                              {open && <PlusCircle className="h-3 w-3 group-hover/btn:scale-125 transition-transform" />}
                            </span>
                          </button>
                          <div className="flex justify-between px-1 text-[9px] font-bold text-slate-400">
                            <span className="uppercase tracking-tighter">Window: {window?.start} - {window?.end}</span>
                            {open && <span className="text-green-500 animate-pulse">LIVE</span>}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
              {approvedHospitals.length === 0 && (
                <div className="sm:col-span-2 p-12 text-center bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl">
                  <Building2 className="h-8 w-8 text-slate-300 mx-auto mb-4 opacity-30" />
                  <p className="text-sm font-medium text-slate-500">No hospital access yet.</p>
                  <button onClick={() => setActiveTab('directory')} className="text-xs text-indigo-600 font-bold mt-2 hover:underline underline-offset-4 tracking-tight">Browse Hospital Directory →</button>
                </div>
              )}
            </div>
          </section>

          <section className="space-y-6">
            {/* Active Visiting Pass Section */}
            {currentlyVisiting.length > 0 && (
              <div className="bg-green-600 p-6 rounded-3xl shadow-xl shadow-green-100 border border-green-500 animate-in slide-in-from-right-4">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-black text-white uppercase tracking-widest flex items-center gap-2">
                    <ShieldCheck className="h-4 w-4" /> Visiting Now
                  </h3>
                  <div className="bg-white/20 px-2 py-1 rounded-lg">
                    <span className="text-[10px] font-black text-white uppercase tracking-tighter">Gate Validated</span>
                  </div>
                </div>
                {currentlyVisiting.map(p => (
                  <div key={p.id} className="space-y-4">
                    <p className="font-black text-white text-lg leading-tight">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                    <div className="bg-white/10 p-4 rounded-2xl backdrop-blur-sm border border-white/10">
                      <div className="flex justify-between items-center text-white">
                        <div>
                          <p className="text-[9px] font-black uppercase opacity-60">Session</p>
                          <p className="text-xs font-black">{p.session}</p>
                        </div>
                        <div className="text-right">
                          <p className="text-[9px] font-black uppercase opacity-60">Entry Time</p>
                          <p className="text-xs font-black">{new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
              <h3 className="text-lg font-bold mb-6 flex items-center justify-between gap-2 text-slate-800">
                <span className="flex items-center gap-2"><QrCode className="h-5 w-5 text-indigo-500" /> Ready for Entry</span>
                {activePassesToday.length > 0 && (
                  <button 
                    onClick={() => setIsScanning(true)}
                    className="flex items-center gap-1.5 bg-indigo-600 text-white px-3 py-1.5 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 transition-all shadow-md active:scale-95 animate-bounce"
                  >
                    <Camera className="h-3.5 w-3.5" /> Scan Gate QR
                  </button>
                )}
              </h3>
              <div className="space-y-4">
                {activePassesToday.map(p => (
                  <div key={p.id} className="p-4 bg-indigo-50 border-2 border-indigo-100 rounded-2xl shadow-sm">
                    <div className="flex justify-between items-center mb-3">
                       <div className="flex items-center gap-1.5">
                        {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : p.session === 'EVENING' ? <Moon className="h-3 w-3 text-indigo-400" /> : <Maximize className="h-3 w-3 text-indigo-500" />}
