import React, { useState, useEffect, createContext, useContext, useRef } from 'react';
import { storageService } from './services/storageService';
import { lotteryService } from './services/lotteryService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import { User, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase, Hospital as HospitalIcon, ArrowRight, Zap } from 'lucide-react';
import { UserRole, AuthUser, SessionType } from './types';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  const autoRunLogs = useRef<Set<string>>(new Set());

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { 
      setUser(session); 
      setView('DASHBOARD'); 
    }

    const automationInterval = setInterval(() => {
      const now = new Date();
      const today = now.toLocaleDateString('en-CA');
      const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
      const currentTimeNum = now.getHours() * 100 + now.getMinutes();

      const hospitals = storageService.getHospitals();

      // 1. Handle Automatic Pass Expiration
      const allPasses = storageService.getPasses();
      let hasPassChanges = false;
      const updatedPasses = allPasses.map(p => {
        // Only expire passes for today that haven't entered yet or were used and reached their cut-off
        if (p.passDate === today && p.entryStatus !== 'expired') {
          let shouldExpire = false;

          if (p.session === 'MORNING' && currentTimeNum >= 1300) shouldExpire = true; // Expires at 1 PM
          if (p.session === 'EVENING' && currentTimeNum >= 2000) shouldExpire = true; // Expires at 8 PM
          if (p.session === 'FULL_DAY' && currentTimeNum >= 2000) shouldExpire = true; // Expires at 8 PM

          if (shouldExpire) {
            hasPassChanges = true;
            return { ...p, entryStatus: 'expired' as const };
          }
        }
        return p;
      });

      if (hasPassChanges) {
        storageService.savePasses(updatedPasses);
      }

      // 2. Handle Automatic Lottery Triggering
      hospitals.forEach(hosp => {
        if (!hosp.isActive || !hosp.autoLotteryEnabled) return;

        (['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).forEach(sess => {
          const isEnabled = hosp.autoLotteryEnabled?.[sess];
          const triggerTime = hosp.autoLotteryTimes?.[sess];

          if (isEnabled && triggerTime && currentTimeStr >= triggerTime) {
            const logKey = `${hosp.id}-${today}-${sess}`;
            if (!autoRunLogs.current.has(logKey)) {
              const result = lotteryService.runLottery(hosp.id, sess);
              if (result.success) {
                console.log(`[AUTOMATION] Triggered lottery for ${hosp.name} (${sess})`);
                autoRunLogs.current.add(logKey);
                const currentUser = storageService.getCurrentUser();
                if (currentUser?.hospitalId === hosp.id && currentUser.role === 'ADMIN') {
                  showFeedback(`Scheduled lottery for ${sess} executed automatically!`, 'success');
                }
              } else {
                if (result.message === "No applications found.") {
                   autoRunLogs.current.add(logKey);
                }
              }
            }
          }
        });
      });
    }, 15000);

    return () => clearInterval(automationInterval);
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();

    if (role === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.loginId === mobile);
      if (existing) {
        if (existing.status === 'suspended') {
          showFeedback("Your account has been suspended by your company.", 'error');
          return;
        }
        if (existing.password && existing.password !== password) {
          showFeedback("Invalid credentials.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: existing.id, 
          fullName: existing.fullName, 
          role: 'MR', 
          companyName: existing.companyName, 
          loginId: existing.loginId,
          mobileNumber: existing.mobileNumber 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Welcome back, ${u.fullName}!`);
      } else {
        showFeedback("Medical Representative not found.", 'error');
      }
    } else if (role === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === mobile);
      if (found && found.adminPassword === password) {
        if (!found.isActive) {
          showFeedback("Company access is deactivated.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: found.id, 
          role: 'COMPANY_ADMIN', 
          fullName: `${found.name} Admin`,
          companyId: found.id 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Pharma Admin session: ${found.name}`);
      } else {
        showFeedback("Invalid Company Admin credentials.", 'error');
      }
    } else if (role === 'ADMIN' || role === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === mobile && u.role === role);

      if (found) {
        if (found.password === password) {
          const u: AuthUser = { 
            id: found.id,
            role: found.role, 
            fullName: found.fullName, 
            hospitalId: found.hospitalId,
            mobileNumber: found.mobileNumber
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Logged in as ${found.fullName}`);
        } else {
          showFeedback("Invalid password for this account.", 'error');
        }
      } else {
        showFeedback(`${role} credentials not found. Check with Super Admin.`, 'error');
      }
    } else if (role === 'SUPER_ADMIN') {
      if (mobile === 'root' && password === 'root') {
        const u: AuthUser = { id: 'sa-1', role: 'SUPER_ADMIN', fullName: 'MedPass Authority' };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback("Super Admin session started.");
      } else {
        showFeedback("Invalid Super Admin Credentials", 'error');
      }
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); 
    setMobile(phone);
    setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex flex-col items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden mb-12">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
