/**
 * Helper to check if a pass is currently within its allowed scanning window
 */
const getScanStatus = (session: SessionType) => {
  const now = new Date();
  const currentTime = now.getHours() * 100 + now.getMinutes(); // format: HHmm (e.g. 1345 for 1:45 PM)

  switch (session) {
    case 'MORNING':
      // 8:00 AM (0800) to 11:45 AM (1145)
      if (currentTime >= 800 && currentTime <= 1145) return { open: true, message: 'Scan Window Open' };
      return { open: false, message: 'Window: 08:00 - 11:45' };
    case 'EVENING':
      // 1:00 PM (1300) to 8:00 PM (2000)
      if (currentTime >= 1300 && currentTime <= 2000) return { open: true, message: 'Scan Window Open' };
      return { open: false, message: 'Window: 13:00 - 20:00' };
    case 'FULL_DAY':
      // 8:00 AM (0800) to 10:30 PM (2230)
      if (currentTime >= 800 && currentTime <= 2230) return { open: true, message: 'Scan Window Open' };
      return { open: false, message: 'Window: 08:00 - 22:30' };
    default:
      return { open: false, message: 'Closed' };
  }
};

/**
 * Dedicated Scanner Component to handle its own lifecycle and video ref
 */
const QRScannerModal: React.FC<{
  onClose: () => void;
  onScan: (value: string) => void;
  mrId: string;
}> = ({ onClose, onScan, mrId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let activeStream: MediaStream | null = null;

    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' } 
        });
        activeStream = s;
        setStream(s);
        if (videoRef.current) {
          videoRef.current.srcObject = s;
          setTimeout(() => {
            videoRef.current?.play().catch(console.error);
          }, 150);
        }
      } catch (err) {
        console.error("Camera access error:", err);
        setError("Could not access camera. Please check permissions.");
      }
    }

    setupCamera();

    return () => {
      if (activeStream) {
        activeStream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const handleSimulateAuto = () => {
    const currentPasses = storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    const myPassesToday = currentPasses.filter(p => 
      p.mrId === mrId && 
      p.passDate === today && 
      p.entryStatus === 'not_entered'
    );

    // Filter by scanning window before allowing auto-simulate
    const validPass = myPassesToday.find(p => getScanStatus(p.session).open);

    if (validPass) {
      onScan(`MEDPASS-GATE-${validPass.hospitalId}`);
    } else {
      onScan(""); // Trigger the manual prompt fallback
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="w-full max-w-md relative flex flex-col items-center">
        <button 
          onClick={onClose} 
          className="absolute -top-16 right-0 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all active:scale-90"
        >
          <X className="h-6 w-6" />
        </button>

        <div className="w-full aspect-square bg-black rounded-[3rem] border-4 border-white/20 overflow-hidden relative shadow-2xl ring-4 ring-indigo-500/20">
          {error ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center">
              <AlertCircle className="h-12 w-12 text-red-500 mb-4" />
              <p className="text-white font-bold">{error}</p>
            </div>
          ) : (
            <>
              <video 
                ref={videoRef} 
                autoPlay 
                playsInline 
                muted 
                className="w-full h-full object-cover" 
              />
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-64 h-64 border-2 border-indigo-400/50 rounded-3xl relative">
                  <div className="absolute top-0 left-0 w-10 h-10 border-t-4 border-l-4 border-indigo-500 rounded-tl-lg"></div>
                  <div className="absolute top-0 right-0 w-10 h-10 border-t-4 border-r-4 border-indigo-500 rounded-tr-lg"></div>
                  <div className="absolute bottom-0 left-0 w-10 h-10 border-b-4 border-l-4 border-indigo-500 rounded-bl-lg"></div>
                  <div className="absolute bottom-0 right-0 w-10 h-10 border-b-4 border-r-4 border-indigo-500 rounded-br-lg"></div>
                  <div className="w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent absolute top-0 animate-[scan_2s_ease-in-out_infinite] shadow-[0_0_15px_rgba(99,102,241,0.8)]"></div>
                </div>
              </div>
            </>
          )}
        </div>

        <div className="mt-8 text-center space-y-4">
          <div className="flex items-center gap-3 justify-center">
            <Smartphone className="h-6 w-6 text-indigo-400" />
            <h3 className="text-xl font-black text-white">Align with Gate QR</h3>
          </div>
          <p className="text-indigo-200/60 text-[10px] font-black uppercase tracking-[0.2em]">Lens active • Looking for security code</p>

          <div className="pt-8">
            <button 
              onClick={handleSimulateAuto} 
              className="px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs hover:bg-indigo-700 transition-all flex items-center gap-3 mx-auto shadow-xl shadow-indigo-900/40 active:scale-95"
            >
              SIMULATE GATE DETECTION <Zap className="h-4 w-4" />
            </button>
          </div>
        </div>
      </div>

      <style>{`
        @keyframes scan {
          0%, 100% { top: 0%; opacity: 0.5; }
          50% { top: 100%; opacity: 1; }
        }
      `}</style>
    </div>
  );
};

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [time, setTime] = useState(new Date());

  // Validation State
  const [validatedPass, setValidatedPass] = useState<IssuedPass | null>(null);
  const [countdown, setCountdown] = useState(60);

  useEffect(() => { 
    refreshData(); 
    const timer = setInterval(() => setTime(new Date()), 30000); // Refresh time every 30s
    return () => clearInterval(timer);
  }, []);

  // Countdown timer for validated entry
  useEffect(() => {
    let timer: number;
    if (validatedPass && countdown > 0) {
      timer = window.setInterval(() => {
        setCountdown(prev => prev - 1);
      }, 1000);
    } else if (countdown === 0) {
      setValidatedPass(null);
      setCountdown(60);
    }
    return () => clearInterval(timer);
  }, [validatedPass, countdown]);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);

    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const handleScanDetected = (qrValueInput?: string) => {
    const latestPasses = storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');

    let qrValue = qrValueInput;

    if (!qrValue) {
       qrValue = prompt("Please enter the Gate Identifier shown on the security screen (e.g. MEDPASS-GATE-h1):");
    }

    if (!qrValue || !qrValue.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid scan format. Please try again.", "error");
      return;
    }

    const hospitalId = qrValue.replace('MEDPASS-GATE-', '');

    // Fix: Filter all matching passes and pick the one that is currently open
    const myEligiblePasses = latestPasses.filter(p => 
      p.mrId === user.id &&
      p.hospitalId === hospitalId && 
      p.passDate === today && 
      p.entryStatus === 'not_entered'
    );

    if (myEligiblePasses.length === 0) {
      showFeedback(`No active pass found for this hospital today.`, "error");
      return;
    }

    // Attempt to find the pass where the window is currently open
    const activePass = myEligiblePasses.find(p => getScanStatus(p.session).open);

    if (!activePass) {
      // If none are open, show the specific error for the first one found as a fallback
      const scanStatus = getScanStatus(myEligiblePasses[0].session);
      showFeedback(`Scan Window Closed for ${myEligiblePasses[0].session}: ${scanStatus.message}`, "error");
      return;
    }

    const updatedPasses = latestPasses.map(p => 
      p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p
    );

    const log = {
      id: Math.random().toString(36).substr(2, 9),
      issuedPassId: activePass.id,
      entryTime: new Date().toISOString(),
      verifiedBy: 'Self-Gate-Scanner'
    };

    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...storageService.getLogs(), log]);

    setIsScanning(false);
    setValidatedPass(activePass);
    setCountdown(60);
    refreshData();
    showFeedback("Access Granted! Proceed through the gate.", 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');

    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { showFeedback(reason || "Ineligible", 'error'); return; }

    const todayStr = new Date().toLocaleDateString('en-CA');
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Application already submitted for this session today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      showFeedback("Pass application submitted successfully!");
    }, 600);
  };

  const requestApproval = (hospitalId: string) => {
    const existing = approvals.find(a => a.mrId === user.id && a.hospitalId === hospitalId);
    if (existing && existing.status !== 'rejected') return;

    const newApproval: MRHospitalApproval = {
      id: 'apprv-' + Math.random().toString(36).substr(2, 9),
      mrId: user.id,
      hospitalId,
      status: 'pending',
      updatedAt: new Date().toISOString()
    };

    const updated = existing 
      ? approvals.map(a => a.id === existing.id ? newApproval : a)
      : [...approvals, newApproval];

    storageService.saveApprovals(updated);
    refreshData();
    showFeedback("Access request sent to hospital admin.");
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  const availableHospitals: Hospital[] = hospitals.filter(h => h.isActive && 
    !approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  ).filter(h => h.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const todayStr = new Date().toLocaleDateString('en-CA');
  const activePassesToday = passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === todayStr);
  const currentlyVisiting = passes.filter(p => p.entryStatus === 'entered' && p.passDate === todayStr);

  return (
    <div className="space-y-6">
      {/* Post-Scan Approval Screen Overlay */}
      {validatedPass && (
        <div className="fixed inset-0 z-[110] bg-green-600 flex flex-col items-center justify-center p-8 animate-in zoom-in duration-300">
          <div className="w-full max-w-sm text-center">
            <div className="bg-white/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8 animate-pulse">
              <CheckCircle2 className="h-16 w-16 text-white" />
            </div>
            <h2 className="text-4xl font-black text-white mb-2 tracking-tighter">STATUS: APPROVED</h2>
            <p className="text-green-100 font-bold uppercase tracking-widest text-sm mb-12">Access granted • Entry Validated</p>

            <div className="bg-white/10 rounded-[2.5rem] p-10 backdrop-blur-md border border-white/20 shadow-2xl">
              <p className="text-white/60 text-xs font-black uppercase tracking-widest mb-2">Gate Timer Active</p>
              <div className="text-8xl font-black text-white tabular-nums tracking-tighter">
                {countdown}
              </div>
              <p className="text-white/80 text-sm font-bold mt-4">Seconds remaining for entry</p>
            </div>

            <button 
              onClick={() => setValidatedPass(null)}
              className="mt-12 px-8 py-4 bg-white text-green-700 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl active:scale-95 transition-all"
            >
              CLOSE STATUS
            </button>
          </div>
        </div>
      )}

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> My Profile</button>
      </div>

      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Analyzing your profile and calculating your ranking factors..."}</p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 lg:col-span-2">
