/**
 * Business Rules for Scanning Windows:
 * Morning:   Scan 08:00 AM - 11:45 AM. (Expires 1:00 PM)
 * Evening:   Scan 01:00 PM - 08:00 PM. (Expires 8:00 PM)
 * Full Day:  Scan 08:00 AM - 10:30 PM. (Expires 8:00 PM)
 */
const getScanStatus = (session: SessionType) => {
  const now = new Date();
  const currentTime = now.getHours() * 100 + now.getMinutes(); 

  switch (session) {
    case 'MORNING':
      if (currentTime >= 800 && currentTime <= 1145) return { open: true, message: 'Morning Window Open', range: '08:00 - 11:45' };
      return { open: false, message: 'Closed: Morning Scan (08:00 - 11:45)', range: '08:00 - 11:45' };
    case 'EVENING':
      if (currentTime >= 1300 && currentTime <= 2000) return { open: true, message: 'Evening Window Open', range: '13:00 - 20:00' };
      return { open: false, message: 'Closed: Evening Scan (13:00 - 20:00)', range: '13:00 - 20:00' };
    case 'FULL_DAY':
      if (currentTime >= 800 && currentTime <= 2230) return { open: true, message: 'Full Day Window Open', range: '08:00 - 22:30' };
      return { open: false, message: 'Closed: Full Day Scan (08:00 - 22:30)', range: '08:00 - 22:30' };
    default:
      return { open: false, message: 'Closed', range: '--:--' };
  }
};

const getExpiryTimeLabel = (session: SessionType) => {
  if (session === 'MORNING') return '01:00 PM';
  return '08:00 PM';
};

const QRScannerModal: React.FC<{
  onClose: () => void;
  onScan: (value: string) => void;
  mrId: string;
}> = ({ onClose, onScan, mrId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [error, setError] = useState<string | null>(null);
  const { showFeedback } = useContext(FeedbackContext);

  useEffect(() => {
    let activeStream: MediaStream | null = null;
    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        activeStream = s;
        if (videoRef.current) {
          videoRef.current.srcObject = s;
          setTimeout(() => { videoRef.current?.play().catch(console.error); }, 150);
        }
      } catch (err) {
        setError("Camera access denied. Please allow permissions.");
      }
    }
    setupCamera();
    return () => { if (activeStream) activeStream.getTracks().forEach(track => track.stop()); };
  }, []);

  const handleSimulateAuto = () => {
    const currentPasses = storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    const myPassesToday = currentPasses.filter(p => p.mrId === mrId && p.passDate === today && p.entryStatus === 'not_entered');

    // Find a pass that is currently in an open window
    const validPass = myPassesToday.find(p => getScanStatus(p.session).open);

    if (validPass) {
      showFeedback(`Simulating: Scan Gate for ${storageService.getHospitals().find(h => h.id === validPass.hospitalId)?.name}`, "success");
      onScan(`MEDPASS-GATE-${validPass.hospitalId}`);
    } else if (myPassesToday.length > 0) {
      showFeedback("You have passes, but scanning windows are currently closed.", "error");
    } else {
      showFeedback("No pending passes found to simulate with.", "error");
    }
  };

  const handleManualEntry = () => {
    const code = prompt("Enter Gate QR Code (e.g. MEDPASS-GATE-h1):");
    if (code) onScan(code);
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="w-full max-w-md relative flex flex-col items-center">
        <button onClick={onClose} className="absolute -top-16 right-0 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all active:scale-90"><X className="h-6 w-6" /></button>

        <div className="w-full aspect-square bg-black rounded-[3.5rem] border-4 border-white/10 overflow-hidden relative shadow-2xl ring-4 ring-indigo-500/20">
          {error ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center"><AlertCircle className="h-12 w-12 text-red-500 mb-4" /><p className="text-white font-bold">{error}</p></div>
          ) : (
            <>
              <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover opacity-60" />
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-64 h-64 border-2 border-indigo-400/30 rounded-[3rem] relative">
                  <div className="absolute top-0 left-0 w-12 h-12 border-t-4 border-l-4 border-indigo-500 rounded-tl-3xl"></div>
                  <div className="absolute top-0 right-0 w-12 h-12 border-t-4 border-r-4 border-indigo-500 rounded-tr-3xl"></div>
                  <div className="absolute bottom-0 left-0 w-12 h-12 border-b-4 border-l-4 border-indigo-500 rounded-bl-3xl"></div>
                  <div className="absolute bottom-0 right-0 w-12 h-12 border-b-4 border-r-4 border-indigo-500 rounded-br-3xl"></div>
                  <div className="w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent absolute top-0 animate-[scan_2s_ease-in-out_infinite] shadow-[0_0_20px_rgba(99,102,241,1)]"></div>
                </div>
              </div>
              <div className="absolute bottom-8 inset-x-0 text-center">
                 <p className="text-white/40 text-[10px] font-black tracking-widest uppercase animate-pulse">Scanning Terminal...</p>
              </div>
            </>
          )}
        </div>

        <div className="mt-10 grid grid-cols-1 gap-4 w-full">
          <div className="flex items-center gap-3 justify-center mb-2">
            <Smartphone className="h-6 w-6 text-indigo-400" />
            <h3 className="text-xl font-black text-white">Align with Gate QR</h3>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <button onClick={handleSimulateAuto} className="px-6 py-4 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase hover:bg-indigo-700 transition-all flex items-center justify-center gap-2 shadow-xl active:scale-95">
              <Zap className="h-4 w-4" /> Auto Detect
            </button>
            <button onClick={handleManualEntry} className="px-6 py-4 bg-white/10 text-white rounded-2xl font-black text-[10px] uppercase hover:bg-white/20 transition-all flex items-center justify-center gap-2 border border-white/10 active:scale-95">
              <Keyboard className="h-4 w-4" /> Enter Code
            </button>
          </div>
        </div>
      </div>
      <style>{` @keyframes scan { 0%, 100% { top: 0%; opacity: 0.2; } 50% { top: 100%; opacity: 1; } } `}</style>
    </div>
  );
};

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [searchTerm, setSearchTerm] = useState('');
  const [isScanning, setIsScanning] = useState(false);
  const [validatedPass, setValidatedPass] = useState<IssuedPass | null>(null);
  const [countdown, setCountdown] = useState(60);

  useEffect(() => { 
    refreshData(); 
    const timer = setInterval(refreshData, 30000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    let timer: number;
    if (validatedPass && countdown > 0) {
      timer = window.setInterval(() => setCountdown(prev => prev - 1), 1000);
    } else if (countdown === 0) {
      setValidatedPass(null);
      setCountdown(60);
    }
    return () => clearInterval(timer);
  }, [validatedPass, countdown]);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })), user.fullName);
    setAiInsight(insight);
  };

  const handleScanDetected = (qrValue: string) => {
    const latestPasses = storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');

    // 1. Strict Format Validation
    if (!qrValue || !qrValue.startsWith('MEDPASS-GATE-')) {
      showFeedback("Invalid Gate QR. Please scan a unique MedPass Gate code.", "error");
      setIsScanning(false);
      return;
    }

    // 2. Extract Targeted Hospital
    const hospitalIdFromQR = qrValue.replace('MEDPASS-GATE-', '');
    const targetHosp = storageService.getHospitals().find(h => h.id === hospitalIdFromQR);

    // 3. Check globally for ANY valid pass for today
    const myAllPassesToday = latestPasses.filter(p => p.mrId === user.id && p.passDate === today && p.entryStatus === 'not_entered');

    // 4. Isolation Check: Does this MR have a pass for THIS specific hospital?
    const passesForThisHospital = myAllPassesToday.filter(p => p.hospitalId === hospitalIdFromQR);

    if (passesForThisHospital.length === 0) {
      // User requested specific logic: "Try with relevant hospital"
      if (myAllPassesToday.length > 0) {
        const otherHospId = myAllPassesToday[0].hospitalId;
        const otherHospName = storageService.getHospitals().find(h => h.id === otherHospId)?.name || "another facility";
        showFeedback(`Wrong Gate: You have a pass for ${otherHospName}. Please try with the relevant hospital gate.`, "error");
      } else {
        showFeedback(`Access Denied: No active pass found for ${targetHosp?.name || 'this facility'} today.`, "error");
      }
      setIsScanning(false);
      return;
    }

    // 5. Session Window Validation
    const activePass = passesForThisHospital.find(p => getScanStatus(p.session).open);

    if (!activePass) {
      const p = passesForThisHospital[0];
      const status = getScanStatus(p.session);
      showFeedback(`Scan Window Closed: ${status.message}`, "error");
      setIsScanning(false);
      return;
    }

    // 6. Approval Execution
    const updatedPasses = latestPasses.map(p => p.id === activePass.id ? { ...p, entryStatus: 'entered' as const } : p);
    const log = { 
      id: Math.random().toString(36).substr(2, 9), 
      issuedPassId: activePass.id, 
      entryTime: new Date().toISOString(), 
      verifiedBy: 'Self-Gate-Scanner' 
    };

    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...storageService.getLogs(), log]);

    setIsScanning(false);
    setValidatedPass(activePass);
    setCountdown(60);
    refreshData();
    showFeedback(`Gate verified for ${targetHosp?.name}!`, 'success');
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    setLoading(true);
    const todayStr = new Date().toLocaleDateString('en-CA');
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9), mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied', createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { refreshData(); setLoading(false); showFeedback("Application submitted!"); }, 600);
  };

  const todayStr = new Date().toLocaleDateString('en-CA');
  const activePassesToday = passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === todayStr);
  const currentlyVisiting = passes.filter(p => p.entryStatus === 'entered' && p.passDate === todayStr);

  return (
    <div className="space-y-6">
      {/* 60s Approval Countdown Overlay */}
      {validatedPass && (
        <div className="fixed inset-0 z-[110] bg-green-600 flex flex-col items-center justify-center p-8 animate-in zoom-in duration-300">
          <div className="w-full max-w-sm text-center">
            <div className="bg-white/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8 animate-pulse"><CheckCircle2 className="h-16 w-16 text-white" /></div>
            <h2 className="text-4xl font-black text-white mb-2 tracking-tighter uppercase">Gate Open</h2>
            <p className="text-green-100 font-bold uppercase tracking-widest text-[10px] mb-12">Validation Successful • Proceed Now</p>
            <div className="bg-white/10 rounded-[2.5rem] p-10 backdrop-blur-md border border-white/20 shadow-2xl">
              <p className="text-white/60 text-xs font-black uppercase tracking-widest mb-2">Gate Timer</p>
              <div className="text-8xl font-black text-white tabular-nums tracking-tighter">{countdown}</div>
