/**
 * Business Rules for Scanning Windows
 */
const getScanStatus = (session: SessionType) => {
  const now = new Date();
  const currentTime = now.getHours() * 100 + now.getMinutes(); 

  switch (session) {
    case 'MORNING':
      if (currentTime >= 800 && currentTime <= 1145) return { open: true, message: 'Morning Window Open', range: '08:00 - 11:45' };
      return { open: false, message: 'Closed: Morning Scan (08:00 - 11:45)', range: '08:00 - 11:45' };
    case 'EVENING':
      if (currentTime >= 1300 && currentTime <= 2000) return { open: true, message: 'Evening Window Open', range: '13:00 - 20:00' };
      return { open: false, message: 'Closed: Evening Scan (13:00 - 20:00)', range: '13:00 - 20:00' };
    case 'FULL_DAY':
      if (currentTime >= 800 && currentTime <= 2230) return { open: true, message: 'Full Day Window Open', range: '08:00 - 22:30' };
      return { open: false, message: 'Closed: Full Day Scan (08:00 - 22:30)', range: '08:00 - 22:30' };
    default:
      return { open: false, message: 'Closed', range: '--:--' };
  }
};

const getExpiryTimeLabel = (session: SessionType) => {
  if (session === 'MORNING') return '01:00 PM';
  return '08:00 PM';
};

const QRScannerModal: React.FC<{
  onClose: () => void;
  onScan: (value: string) => void;
  mrId: string;
}> = ({ onClose, onScan, mrId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const { showFeedback } = useContext(FeedbackContext);

  useEffect(() => {
    let activeStream: MediaStream | null = null;
    let visionInterval: number;

    async function setupCamera() {
      try {
        const s = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        activeStream = s;
        if (videoRef.current) {
          videoRef.current.srcObject = s;
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play().catch(console.error);
            // Start AI Vision Loop
            startVisionLoop();
          };
        }
      } catch (err) {
        setError("Camera access denied. Please allow permissions.");
      }
    }

    const startVisionLoop = () => {
      // Analyze a frame every 2.5 seconds to balance performance and latency
      visionInterval = window.setInterval(async () => {
        if (!videoRef.current || !canvasRef.current || isProcessing) return;

        const video = videoRef.current;
        const canvas = canvasRef.current;
        const context = canvas.getContext('2d');

        if (context && video.readyState === video.HAVE_ENOUGH_DATA) {
          setIsProcessing(true);
          canvas.width = 480; // Resize for efficient AI processing
          canvas.height = (video.videoHeight / video.videoWidth) * 480;
          context.drawImage(video, 0, 0, canvas.width, canvas.height);

          try {
            const base64Image = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            const response = await ai.models.generateContent({
              model: 'gemini-3-flash-preview',
              contents: [{
                parts: [
                  { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
                  { text: "Locate any QR code in this image. If it contains a string starting with 'MEDPASS-GATE-', return ONLY that string. Otherwise return 'null'. Do not explain." }
                ]
              }]
            });

            const result = response.text?.trim() || 'null';
            if (result !== 'null' && result.startsWith('MEDPASS-GATE-')) {
              onScan(result);
              clearInterval(visionInterval); // Stop scanning once detected
            }
          } catch (err) {
            console.error("AI Vision Error:", err);
          } finally {
            setIsProcessing(false);
          }
        }
      }, 2500);
    };

    setupCamera();
    return () => {
      if (activeStream) activeStream.getTracks().forEach(track => track.stop());
      if (visionInterval) clearInterval(visionInterval);
    };
  }, [onScan, isProcessing]);

  const handleSimulateAuto = () => {
    const currentPasses = storageService.getPasses();
    const today = new Date().toLocaleDateString('en-CA');
    const myPassesToday = currentPasses.filter(p => p.mrId === mrId && p.passDate === today && p.entryStatus === 'not_entered');
    const validPass = myPassesToday.find(p => getScanStatus(p.session).open);

    if (validPass) {
      showFeedback(`Simulating detection for ${storageService.getHospitals().find(h => h.id === validPass.hospitalId)?.name}`, "success");
      onScan(`MEDPASS-GATE-${validPass.hospitalId}`);
    } else {
      showFeedback("No active passes available for simulation right now.", "error");
    }
  };

  const handleManualEntry = () => {
    const code = prompt("Enter Gate QR Code (e.g. MEDPASS-GATE-h1):");
    if (code) onScan(code);
  };

  return (
    <div className="fixed inset-0 z-[100] bg-slate-900/98 backdrop-blur-xl flex flex-col items-center justify-center p-6 animate-in fade-in duration-300">
      <div className="w-full max-w-md relative flex flex-col items-center">
        <button onClick={onClose} className="absolute -top-16 right-0 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all active:scale-90"><X className="h-6 w-6" /></button>

        <div className="w-full aspect-square bg-black rounded-[3.5rem] border-4 border-white/10 overflow-hidden relative shadow-2xl ring-4 ring-indigo-500/20">
          <canvas ref={canvasRef} className="hidden" />
          {error ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center"><AlertCircle className="h-12 w-12 text-red-500 mb-4" /><p className="text-white font-bold">{error}</p></div>
          ) : (
            <>
              <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover opacity-80" />
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="w-64 h-64 border-2 border-white/20 rounded-[3rem] relative">
                  <div className="absolute top-0 left-0 w-12 h-12 border-t-4 border-l-4 border-indigo-500 rounded-tl-3xl shadow-[0_0_15px_rgba(99,102,241,0.5)]"></div>
                  <div className="absolute top-0 right-0 w-12 h-12 border-t-4 border-r-4 border-indigo-500 rounded-tr-3xl shadow-[0_0_15px_rgba(99,102,241,0.5)]"></div>
                  <div className="absolute bottom-0 left-0 w-12 h-12 border-b-4 border-l-4 border-indigo-500 rounded-bl-3xl shadow-[0_0_15px_rgba(99,102,241,0.5)]"></div>
                  <div className="absolute bottom-0 right-0 w-12 h-12 border-b-4 border-r-4 border-indigo-500 rounded-br-3xl shadow-[0_0_15px_rgba(99,102,241,0.5)]"></div>
                  <div className="w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent absolute top-0 animate-[scan_2s_ease-in-out_infinite] shadow-[0_0_20px_rgba(99,102,241,1)]"></div>
                </div>
              </div>

              {/* Vision Status Overlay */}
              <div className="absolute bottom-8 inset-x-0 flex flex-col items-center gap-2">
                 {isProcessing ? (
                   <div className="flex items-center gap-2 bg-indigo-600/90 text-white px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg animate-pulse">
                     <Loader2 className="h-3 w-3 animate-spin" /> AI Vision Processing...
                   </div>
                 ) : (
                   <p className="text-white/40 text-[10px] font-black tracking-widest uppercase">Scanning Gate...</p>
                 )}
              </div>
            </>
          )}
        </div>

        <div className="mt-10 grid grid-cols-1 gap-4 w-full">
          <div className="flex items-center gap-3 justify-center mb-2">
            <Zap className="h-6 w-6 text-indigo-400 animate-pulse" />
            <h3 className="text-xl font-black text-white">AI Vision Scanning</h3>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <button onClick={handleSimulateAuto} className="px-6 py-4 bg-indigo-600 text-white rounded-2xl font-black text-[10px] uppercase hover:bg-indigo-700 transition-all flex items-center justify-center gap-2 shadow-xl active:scale-95">
              <Zap className="h-4 w-4" /> Simulate Find
            </button>
            <button onClick={handleManualEntry} className="px-6 py-4 bg-white/10 text-white rounded-2xl font-black text-[10px] uppercase hover:bg-white/20 transition-all flex items-center justify-center gap-2 border border-white/10 active:scale-95">
              <Keyboard className="h-4 w-4" /> Manual Entry
            </button>
          </div>
        </div>
      </div>
      <style>{` @keyframes scan { 0%, 100% { top: 0%; opacity: 0.2; } 50% { top: 100%; opacity: 1; } } `}</style>
    </div>
  );
};

